  const left = labelCap + 14, valueTexts = series.values.map((value) => ctx.format(value, field));
  const labels = data.categories.map((category) => ctx.wrap(String(category), labelCap, 12, 500));
  const noFirst = isEnglish(ctx.lang) ? 'first step unavailable' : '首步为0，比例不可计算';
  const firstShares = series.values.map((value) => first > 0
    ? `${isEnglish(ctx.lang) ? 'Of first' : '占首步'} ${ctx.percent(value / first)}` : noFirst);
  const previousShares = series.values.map((value, i) => i === 0 ? '' : series.values[i - 1] > 0
    ? `${isEnglish(ctx.lang) ? 'Of previous' : '占上一步'} ${ctx.percent(value / series.values[i - 1])}` : noFirst);
  const readoutWidth = Math.max(32, ...valueTexts.map((text) => labelWidth(ctx, text, 14, 700)),
    ...firstShares.map((text) => labelWidth(ctx, text)), ...previousShares.map((text) => labelWidth(ctx, text)));
