  const barW = Math.max(24, chartWidth - left - readoutWidth - 18);
  const rowH = Math.max(64, ...labels.map((lines) => lines.length * 15 + barH + 14));
  const children = [];
  data.categories.forEach((category, i) => {
    const rowTop = top + i * rowH, centerY = rowTop + rowH / 2 - 2;
    const label = labels[i];
    children.push(ctx.textLines(left - 12, centerY + 4 - ((label.length - 1) * 8), label, { anchor: 'end', fill: ctx.color('fg'), meta: { kind: 'category', label: category, index: i } }));
    children.push(ctx.rect(left, centerY - barH / 2, barW, barH, { rx: barH / 2, fill: ctx.color('grid') }));
    const length = maxValue > 0 ? series.values[i] / maxValue * barW : 0;
    const record = data.rows[i]?.[spec.encode.id] ?? `${i}`;
    // 漏斗各步的颜色没有图例含义，选中步骤可以改用强调色。
