  const keepsValue = edge === value || (valueFirst ? edge.startsWith(`${value} `) : edge.endsWith(` ${value}`));
  if (keepsValue || ctx.measure(value) > width) return lines;
  // 读数放得下一整行时，数字和单位不能被名称挤到两行。
  const nameLines = sideLabels(ctx, name, width);
  const index = valueFirst ? 0 : nameLines.length - 1;
  const joined = join(nameLines[index]);
  if (ctx.measure(joined) <= width) {
    nameLines[index] = joined;
    return nameLines;
  }
