  const values = ctx.table(spec).categories;
  const slot = plot.w / Math.max(1, values.length);
  const positions = new Map(values.map((value, i) => [value, plot.x + slot * (i + 0.5)]));
  // 类别名在空白、连字符、斜杠后可换行（如 2026-01 → 2026- / 01）。可抽稀的类别名（如 K 线日期）
  // 在某个不可断片段放不进槽时保持单行、按实测间距抽稀，首末两个始终显示；否则逐个显示并换行。
  const pieces = (value) => String(value).split(/(?<=[\s\-/])/).map((piece) => piece.trim()).filter(Boolean);
  const thinned = thin && values.some((value) => pieces(value).some((piece) => ctx.measure(piece, 12, 400) > slot - 8));
  const wrapped = values.map((value) => thinned ? [String(value)] : ctx.wrap(String(value), Math.max(24, slot - 8), 12, 400));
  const shown = wrapped.map(() => true);
  if (thinned) {
    const widthOf = (index) => ctx.measure(wrapped[index][0], 12, 400);
    const fits = (a, b) => positions.get(values[b]) - positions.get(values[a]) >= (widthOf(a) + widthOf(b)) / 2 + 8;
    let previous = 0;
    for (let i = 1; i < values.length; i += 1) {
      shown[i] = fits(previous, i);
      if (shown[i]) previous = i;
    }
    const last = values.length - 1;
    if (last > 0 && !shown[last]) {
      while (previous > 0 && !fits(previous, last)) {
        shown[previous] = false;
        do previous -= 1; while (previous > 0 && !shown[previous]);
      }
      shown[last] = fits(previous, last);
    }
  }
  for (let i = 0; i < values.length; i += 1) {
    if (!shown[i]) continue;
    children.push(ctx.textLines(positions.get(values[i]), plot.y + plot.h + 20, wrapped[i], { anchor: 'middle', size: 12, fill: ctx.color('muted') }));
  }
  const visibleLines = wrapped.filter((_, index) => shown[index]);
  return { values, slot, positions, category, maxLabelLines: Math.max(1, ...visibleLines.map((lines) => lines.length)) };
}

function annotations(spec, ctx, plot, y, children, roles) {
  for (const item of spec.annotations || []) {
    if (item.kind === 'note') {
      const idField = field(spec, 'id');
      const index = spec.data.findIndex((row) => row[idField] === item.record);
      if (index < 0 || !roles.has(item.field)) continue;
      const row = spec.data[index];
      const x = plot.x + plot.w * ((ctx.table(spec).categories.indexOf(row[field(spec, 'category')]) + 0.5) / Math.max(1, ctx.table(spec).categories.length));
      const lines = ctx.wrap(item.text, Math.max(48, plot.x + plot.w - x - 12), 12, 400);
      const note = { size: 12, fill: ctx.color('fg'), meta: { kind: 'annotation-note', record: index, id: item.record, field: item.field } };
      if (lines.length === 1) children.push(ctx.text(x + 7, y(row[item.field]) - 7, lines[0], note));
      else children.push(ctx.textLines(x + 7, y(row[item.field]) - 7 - (lines.length - 1) * 16, lines, note));
      continue;
    }
    if (!roles.has(item.field)) continue;
    if (item.kind === 'band') {
      const y1 = y(item.from), y2 = y(item.to);
      children.push(ctx.rect(plot.x, Math.min(y1, y2), plot.w, Math.max(1, Math.abs(y2 - y1)), { fill: ctx.color('tone3'), 'fill-opacity': 0.12 }));
    } else if (item.kind === 'rule') {
      const yy = y(item.value);
      children.push(ctx.line(plot.x, yy, plot.x + plot.w, yy, { stroke: ctx.color('tone3'), 'stroke-width': 1, 'stroke-dasharray': '4 3' }));
    } else continue;
    if (item.label) {
      const lines = ctx.wrap(item.label, Math.max(48, Math.min(plot.w - 8, 220)), 12, 400);
      const py = y(item.value ?? item.to) - 4 - (lines.length - 1) * 16;
      children.push(ctx.textLines(plot.x + plot.w - 3, py, lines, { anchor: 'end', size: 12, fill: ctx.textColor('tone3') }));
    }
  }
}

function finish(ctx, children, plot, cat, width, footer = []) {
  let y = plot.y + plot.h + 40 + (cat.maxLabelLines - 1) * 16;
  const readouts = [];
  for (const item of footer) {
    const lines = ctx.wrap(item.text, width - plot.x - RIGHT, 12, 400);
    readouts.push(ctx.textLines(plot.x, y, lines, { size: 12, fill: ctx.color('muted'), meta: item.meta }));
    y += lines.length * 16 + 3;
  }
  if (readouts.length) children.push(ctx.el('g', { opacity: 0.68 }, readouts));
  return { ...ctx.scene(Math.max(plot.y + plot.h + 48 + (cat.maxLabelLines - 1) * 16, y + (footer.length ? 8 : 0)), children), width };
}

function interval(spec, ctx) {
  const low = field(spec, 'low'), high = field(spec, 'high'), estimate = field(spec, 'value');
  const nums = spec.data.flatMap((row) => [row[low], row[high], estimate ? row[estimate] : null]);
  const roles = new Set([low, high, estimate]);
  const f = chartFrame(spec, ctx, nums, low, false, [...roles]);
  const cat = categories(spec, ctx, f.plot, f.children);
  annotations(spec, ctx, f.plot, f.y, f.children, roles);
  const footer = [];
  for (let i = 0; i < spec.data.length; i += 1) {
    const row = spec.data[i], x = cat.positions.get(row[cat.category]);
    if (x === undefined) continue;
    const y1 = f.y(row[low]), y2 = f.y(row[high]);
    const meta = { kind: 'interval', record: i, id: row[field(spec, 'id')] ?? String(i), value: [row[low], row[high]] };
    f.children.push(ctx.line(x, y1, x, y2, { stroke: ctx.color('ink'), 'stroke-width': 1.2, meta }));
    const cap = Math.min(8, cat.slot * 0.16);
    f.children.push(ctx.line(x - cap, y1, x + cap, y1, { stroke: ctx.color('ink'), 'stroke-width': 1.2 }));
    f.children.push(ctx.line(x - cap, y2, x + cap, y2, { stroke: ctx.color('ink'), 'stroke-width': 1.2 }));
    if (estimate) f.children.push(ctx.circle(x, f.y(row[estimate]), 3.2, { fill: ctx.color('accent'), stroke: ctx.color('bg'), 'stroke-width': 1, meta: { kind: 'estimate', record: i, id: meta.id, value: row[estimate] } }));
    footer.push({
      text: `${String(row[cat.category])}: ${ctx.format(row[low], low)} – ${ctx.format(row[high], high)}${estimate ? ` · ${ctx.format(row[estimate], estimate)}` : ''}`,
      meta: { kind: 'interval-readout', record: i, id: meta.id, value: { low: row[low], high: row[high], estimate: estimate ? row[estimate] : null } },
    });
  }
  return finish(ctx, f.children, f.plot, cat, f.width, footer);
}

function candlestick(spec, ctx) {
  const open = field(spec, 'open'), close = field(spec, 'close'), low = field(spec, 'low'), high = field(spec, 'high');
  const values = spec.data.flatMap((row) => [row[open], row[close], row[low], row[high]]);
  const fields = [open, close, low, high];
  const f = chartFrame(spec, ctx, values, low, false, fields, { thin: true });
  const cat = categories(spec, ctx, f.plot, f.children, { thin: true });
  annotations(spec, ctx, f.plot, f.y, f.children, new Set(fields));
  for (let i = 0; i < spec.data.length; i += 1) {
    const row = spec.data[i], x = cat.positions.get(row[field(spec, 'category')]);
    if (x === undefined) continue;
    const rising = row[close] >= row[open];
    const top = f.y(Math.max(row[open], row[close]));
    const bottom = f.y(Math.min(row[open], row[close]));
    const bodyW = Math.max(3, Math.min(16, cat.slot * 0.46));
    const id = row[field(spec, 'id')] ?? String(i);
    const meta = { kind: 'candlestick', record: i, id, value: { open: row[open], close: row[close], low: row[low], high: row[high], direction: rising ? 'up' : 'down' } };
    f.children.push(ctx.line(x, f.y(row[high]), x, f.y(row[low]), { stroke: ctx.color('ink'), 'stroke-width': 1, meta: { kind: 'candle-wick', record: i, id } }));
    if (row[open] === row[close]) {
      f.children.push(ctx.line(x - bodyW / 2, top, x + bodyW / 2, top, { stroke: ctx.color('ink'), 'stroke-width': 1.5, meta }));
    } else {
      f.children.push(ctx.rect(x - bodyW / 2, top, bodyW, bottom - top, {
        fill: rising ? ctx.color('bg') : ctx.color('ink'), stroke: ctx.color('ink'), 'stroke-width': 1.1, meta,
      }));
    }
  }
  const directions = new Set(spec.data.map((row) => row[close] > row[open] ? 'up' : row[close] < row[open] ? 'down' : 'flat'));
  const english = /^en(?:-|$)/i.test(ctx.lang);
  const legendItems = [
    ...(directions.has('up') ? [{ label: english ? 'Rising · hollow' : '上涨 · 空心', color: ctx.color('ink'), mark: 'hollow' }] : []),
    ...(directions.has('down') ? [{ label: english ? 'Falling · filled' : '下跌 · 实心', color: ctx.color('ink'), mark: 'filled' }] : []),
    ...(directions.has('flat') ? [{ label: english ? 'Unchanged · line' : '持平 · 横线', color: ctx.color('ink'), mark: 'line' }] : []),
  ];
  const legend = ctx.legend(legendItems, f.plot.w);
  // Each legend entry is a group holding its swatch; restyle that swatch to match the candle it stands for.
  legend.children.forEach((group, i) => {
    const swatch = group.children.find((child) => child.tag === 'rect');
    const { mark } = legendItems[i];
    if (!swatch || mark === 'filled') return;
    if (mark === 'hollow') Object.assign(swatch.attrs, { fill: ctx.color('bg'), stroke: ctx.color('ink'), 'stroke-width': 1.1 });
    else group.children[group.children.indexOf(swatch)] = ctx.line(swatch.attrs.x, swatch.attrs.y + 5, swatch.attrs.x + 10, swatch.attrs.y + 5, { stroke: ctx.color('ink'), 'stroke-width': 1.5 });
  });
  f.children.push(ctx.el('g', { transform: `translate(${f.plot.x},${f.plot.y - 20})` }, legend.children));
  return finish(ctx, f.children, f.plot, cat, f.width);
}

function strip(spec, ctx) {
  const value = field(spec, 'value');
  const vals = spec.data.map((row) => row[value]);
  const f = chartFrame(spec, ctx, vals, value);
  const cat = categories(spec, ctx, f.plot, f.children);
  annotations(spec, ctx, f.plot, f.y, f.children, new Set([value]));
  const byCategory = new Map();
  spec.data.forEach((row, index) => {
    const category = row[cat.category];
    if (!byCategory.has(category)) byCategory.set(category, []);
    byCategory.get(category).push({ row, index, y: f.y(row[value]) });
  });
  for (const [category, points] of byCategory) {
    const center = cat.positions.get(category);
    if (center === undefined) continue;
    const placed = [], maxOffset = Math.max(0, cat.slot / 2 - 3);
    points.sort((a, b) => a.y - b.y || a.index - b.index);
    for (const point of points) {
      const candidates = [0, ...Array.from({ length: Math.ceil(maxOffset / 6) }, (_, i) => (i + 1) * 6).flatMap(offset => [-offset, offset])];
      const offset = candidates.find(candidate => Math.abs(candidate) <= maxOffset && placed.every(other => {
        const dx = candidate - other.offset, dy = point.y - other.y;
        return dx * dx + dy * dy >= 36;
      }));
      const safeOffset = offset ?? Math.max(-maxOffset, Math.min(maxOffset, candidates.at(-1)));
      placed.push({ y: point.y, offset: safeOffset });
      const id = point.row[field(spec, 'id')] ?? String(point.index);
      f.children.push(ctx.circle(center + safeOffset, point.y, 3, { fill: ctx.color('ink'), 'fill-opacity': 0.78, meta: { kind: 'strip', record: point.index, id, value: point.row[value] } }));
    }
  }
  return finish(ctx, f.children, f.plot, cat, f.width);
}

function violin(spec, ctx) {
  const category = field(spec, 'category'), density = field(spec, 'density'), median = field(spec, 'median');
  const all = spec.data.flatMap((row) => row[density].map((point) => point[0]).concat(row[median]));
  const f = chartFrame(spec, ctx, all, median);
  const cat = categories(spec, ctx, f.plot, f.children);
  const maxDensity = Math.max(...spec.data.flatMap((row) => row[density].map((point) => point[1])));
  annotations(spec, ctx, f.plot, f.y, f.children, new Set([median]));
  for (let i = 0; i < spec.data.length; i += 1) {
    const row = spec.data[i], x = cat.positions.get(row[category]);
    if (x === undefined) continue;
    const half = Math.min(28, cat.slot * 0.38);
    const left = row[density].map(([v, d]) => `${x - half * d / maxDensity},${f.y(v)}`);
    const right = [...row[density]].reverse().map(([v, d]) => `${x + half * d / maxDensity},${f.y(v)}`);
    const id = row[field(spec, 'id')] ?? String(i);
    const shape = ctx.el('polygon', { points: [...left, ...right].join(' '), fill: ctx.color('bg'), 'fill-opacity': 0.72, stroke: ctx.color('ink'), 'stroke-width': 1 });
    shape.meta = { kind: 'violin', record: i, id };
    f.children.push(shape);
    f.children.push(ctx.line(x - half * 0.48, f.y(row[median]), x + half * 0.48, f.y(row[median]), { stroke: ctx.color('ink'), 'stroke-width': 1.6, meta: { kind: 'median', record: i, id, value: row[median] } }));
  }
  return finish(ctx, f.children, f.plot, cat, f.width);
}

// Registers into the caller's registry so a Node build can assemble an isolated subset.
export function install({ register }) {
  register(['interval', 'candlestick', 'strip', 'violin'], (spec, ctx) => {
    if (spec.chart === 'interval') return interval(spec, ctx);
    if (spec.chart === 'candlestick') return candlestick(spec, ctx);
    if (spec.chart === 'strip') return strip(spec, ctx);
    return violin(spec, ctx);
  });
}

install({ register });

/* 多维趋势与矩阵图族：只构造共享KChart scene，全部格式和测字委托ctx。 */

import { register } from './registry.js';
import { columnHeaders } from '../core/geometry.js';

const finite = Number.isFinite;
const number = (ctx, field, values, zero = false) => {
  const result = ctx.ticks(values.filter(finite), field, { zero });
  const meta = ctx.field(field);
  const min = meta.domain?.[0] ?? result.min;
  const max = meta.domain?.[1] ?? result.max;
  if (zero && !(min <= 0 && max >= 0)) {
    ctx.fit(
      /^en(?:-|$)/i.test(ctx.lang) ? 'This measure requires a domain including zero' : '该度量必须使用包含0的基线范围',
      /^en(?:-|$)/i.test(ctx.lang) ? 'Expand the field domain to include zero' : '扩大字段domain使其包含0后重试',
    );
  }
  if (values.some(v => finite(v) && (v < min || v > max))) {
    ctx.fit(
      /^en(?:-|$)/i.test(ctx.lang) ? 'Values exceed the explicit domain' : '数值超出显式domain',
      /^en(?:-|$)/i.test(ctx.lang) ? 'Expand the field domain and retry' : '扩大字段domain后重试',
    );
  }
  return { min, max, ticks: result.ticks };
};
const chart = (spec, ctx) => {
  const { width } = ctx, enc = spec.encode || {}, pad = { l: 56, r: 28, t: 48, b: 58 };
  const children = [], english = /^en(?:-|$)/i.test(ctx.lang), title = spec.title || spec.chart;
  const msg = (zh, en) => english ? en : zh;
  const plot = (top = pad.t, bottom = 330, left = pad.l + 16, right = width - pad.r - 24) => ({ x: left, y: top, w: Math.max(1, right - left), h: Math.max(1, bottom - top) });
  const bandX = (i, n, p) => p.x + (i + .5) * p.w / n;
  const reserveEdgeCategories = (categories, p) => {
    if (!categories.length) return;
    const widths = categories.map(value => ctx.measure(String(value), 12));
    const minimum = categories.length === 1 ? widths[0] + 16 : (widths[0] + widths.at(-1) + 6) / (1 - 1 / categories.length);
    p.w = Math.max(p.w, minimum);
  };
  const catLabels = (categories, p, y = p.y + p.h + 22) => {
    const n = categories.length, centers = categories.map((_, i) => bandX(i, n, p));
    const widths = categories.map(value => ctx.measure(String(value), 12)), shown = new Set();
    // 类别名居中对齐自己的柱或点；只有首末一个居中后会超出画布时，才改为向内对齐。
    const minX = 2, maxX = Math.max(width, p.x + p.w) - 2;
    const anchors = categories.map((_, i) => {
      if (n > 1 && i === 0 && centers[i] - widths[i] / 2 < minX) return 'start';
      if (n > 1 && i === n - 1 && centers[i] + widths[i] / 2 > maxX) return 'end';
      return 'middle';
    });
    const bounds = i => {
      const left = centers[i] - widths[i] * (anchors[i] === 'start' ? 0 : anchors[i] === 'end' ? 1 : .5);
      return { left, right: left + widths[i] };
    };
    const fits = i => {
      const candidate = bounds(i);
      return candidate.left >= minX && candidate.right <= maxX && [...shown].every(j => {
        const other = bounds(j);
        return candidate.right + 6 <= other.left || other.right + 6 <= candidate.left;
      });
    };
    for (let i = 0; i < n; i++) if (fits(i)) shown.add(i);
    if (n > 1 && !shown.has(n - 1)) {
      const last = n - 1;
      for (const i of [...shown].filter(j => j !== 0).reverse()) {
        shown.delete(i);
        if (fits(last)) break;
        shown.add(i);
      }
      if (fits(last)) shown.add(last);
    }
    for (const i of shown) children.push(ctx.text(centers[i], y, String(categories[i]), { anchor: anchors[i], size: 12 }));
  };
  const legend = (items, y = 350) => {
    const out = ctx.legend(items, width - pad.l - pad.r);
    children.push(ctx.el('g', { transform: `translate(${pad.l},${y})` }, out.children));
    return out.height;
  };
  const endScene = (bottom = 330) => ctx.scene(bottom + 28, children, title);
  const asPath = pts => pts.map((p, i) => `${i ? 'L' : 'M'}${p[0]},${p[1]}`).join(' ');
  const linePath = (values, xs, ys) => {
    let d = '', active = false;
    values.forEach((v, i) => {
      if (!finite(v)) {
        active = false;
        return;
      }
      d += `${active ? 'L' : 'M'}${xs[i]},${ys(v, i)}`;
      active = true;
    });
    return d;
  };
  const data = spec.data || [];

  if (spec.chart === 'stream') {
    const t = ctx.table(spec), cats = t.categories, series = t.series;
    if (series.some(s => s.values.some(v => !finite(v)))) {
      ctx.fit(
        msg('stream需要每个时点都有完整非负序列', 'Stream requires complete, non-negative observations at every time'),
        msg('补齐有效观测或选择允许缺失的图型；不要把缺失当作0', 'Provide complete observations or choose a chart that supports missing values; do not treat missing as zero'),
      );
    }
    const totals = cats.map((_, i) => series.reduce((s, a) => s + a.values[i], 0));
    const maximum = Math.max(1, ...totals), vertical = ctx.ticks([-maximum / 2, maximum / 2], series[0]?.field, { count: 4 });
    // 厚度偏移只写数字：业务单位已经在图例里，再追加会变成「万万元」。
    const offsetLabels = vertical.ticks.map(tick => ctx.format(tick, series[0]?.field, false));
    const gutter = Math.max(36, ...offsetLabels.map(label => ctx.measure(label, 12))) + 16;
    const p = plot(72, 330, gutter, width - 24);
    reserveEdgeCategories(cats, p);
    const xs = cats.map((_, i) => bandX(i, cats.length, p));
    const extent = Math.max(Math.abs(vertical.min), Math.abs(vertical.max)), scale = extent / (p.h / 2);
    const lower = cats.map((_, i) => -totals[i] / 2), center = p.y + p.h / 2;
    vertical.ticks.forEach(tick => {
      const y = center - tick / scale;
      children.push(ctx.line(p.x, y, p.x + p.w, y, { stroke: tick === 0 ? ctx.color('axis') : ctx.color('grid') }));
    });
    series.forEach((s, k) => {
      const top = [], bottom = [];
      s.values.forEach((v, i) => {
        const amount = v || 0;
        bottom.push(lower[i]);
        lower[i] += amount;
        top.push(lower[i]);
      });
      // 上边从左到右、下边从右到左闭合；下边必须按同一时点配对后再反转。
      const toPoint = (v, i) => [xs[i], center - v / scale];
      const points = [...top.map(toPoint), ...bottom.map(toPoint).reverse()];
      children.push(ctx.el('polygon', { points: points.map(q => q.join(',')).join(' '), fill: ctx.color(`tone${k % 6 + 1}`), 'fill-opacity': .82, stroke: ctx.color('bg'), 'stroke-width': 1 }));
    });
    vertical.ticks.forEach((tick, index) => {
      const y = center - tick / scale;
      children.push(ctx.text(p.x - 8, y + 4, offsetLabels[index], { anchor: 'end', size: 12 }));
    });
    children.push(ctx.textLines(p.x, 48, ctx.wrap(msg('纵轴为相对中心的厚度偏移；正值在上，负值在下', 'Vertical axis is thickness offset from center; positive above, negative below'), p.w, 12), { size: 12 }));
    catLabels(cats, p);
    const h = legend(series.map((s, i) => ({
      label: s.label,
      color: ctx.color(`tone${i % 6 + 1}`),
    })), p.y + p.h + 42);
    const scene = endScene(p.y + p.h + 42 + h);
    scene.width = Math.max(width, p.x + p.w + 24);
    return scene;
  }

  if (spec.chart === 'split-compare') {
    const t = ctx.table(spec), cats = t.categories, rowsByCategory = cats.map(c => data.find(r => r[enc.category] === c)), upper = rowsByCategory.map(r => r?.[enc.upper]), lower = rowsByCategory.map(r => r?.[enc.lower]);
    const upperScale = ctx.ticks(upper.filter(finite), enc.upper, { zero: true, count: 4 });
    const lowerScale = ctx.ticks(lower.filter(finite), enc.lower, { zero: true, count: 4, length: 220 });
    const leftGutter = Math.max(36, ...upperScale.labels.map(label => ctx.measure(label, 12))) + 16;
    const rightGutter = Math.max(36, ...lowerScale.labels.map(label => ctx.measure(label, 12))) + 16;
    const p = plot(64, 330, leftGutter, width - rightGutter);
    reserveEdgeCategories(cats, p);
    const mid = p.y + p.h * .48, gap = 28, upH = (mid - p.y) - gap / 2, lowY = mid + gap / 2, lowH = p.y + p.h - lowY;
    const su = { min: upperScale.min, max: upperScale.max, ticks: upperScale.ticks, labels: upperScale.labels };
    const sl = { min: lowerScale.min, max: lowerScale.max, ticks: lowerScale.ticks, labels: lowerScale.labels };
    const uy = v => p.y + (v - su.min) / (su.max - su.min || 1) * upH;
    const ly = v => lowY + lowH - (v - sl.min) / (sl.max - sl.min || 1) * lowH;
    const bw = Math.max(2, p.w / cats.length * .56);
    upper.forEach((v, i) => {
      if (!finite(v)) return;
      const y = uy(v);
      children.push(ctx.rect(bandX(i, cats.length, p) - bw / 2, p.y, bw, Math.max(1, y - p.y), { fill: ctx.color('tone2') }));
    });
    children.push(ctx.line(p.x, p.y, p.x + p.w, p.y, { stroke: ctx.color('axis') }));
    const pts = lower.map((v, i) => [bandX(i, cats.length, p), ly(finite(v) ? v : sl.min)]);
    children.push(ctx.path(`${asPath(pts)} L${pts.at(-1)[0]},${lowY + lowH} L${pts[0][0]},${lowY + lowH} Z`, { fill: ctx.color('tone1'), 'fill-opacity': .18, stroke: 'none' }));
    children.push(ctx.path(asPath(pts), { fill: 'none', stroke: ctx.color('tone1'), 'stroke-width': 2 }));
    su.ticks.forEach((tick, i) => {
      const uyPos = uy(tick);
      children.push(ctx.line(p.x, uyPos, p.x + p.w, uyPos, { stroke: ctx.color('grid') }));
      children.push(ctx.text(p.x - 8, uyPos + 4, su.labels[i], { anchor: 'end', size: 12 }));
    });
    sl.ticks.forEach((tick, i) => {
      const lyPos = ly(tick);
      children.push(ctx.line(p.x, lyPos, p.x + p.w, lyPos, { stroke: ctx.color('grid') }));
      children.push(ctx.text(p.x + p.w + 8, lyPos + 4, sl.labels[i], { anchor: 'start', size: 12 }));
    });
    const axisCaption = (fieldName) => {
      const meta = ctx.field(fieldName);
      const unit = meta.unit || (meta.format === 'percent' ? '%' : '');
      return [meta.label, unit].filter(Boolean).join(' · ');
    };
    children.push(ctx.text(p.x, p.y - 8, axisCaption(enc.upper), { size: 12 }));
    children.push(ctx.text(p.x, lowY - 6, axisCaption(enc.lower), { size: 12 }));
    children.push(ctx.line(p.x, lowY + lowH, p.x + p.w, lowY + lowH, { stroke: ctx.color('axis') }));
    catLabels(cats, { ...p, y: lowY, h: lowH });
    const scene = endScene(p.y + p.h + 36);
    scene.width = Math.max(width, p.x + p.w + rightGutter);
    return scene;
  }

  if (spec.chart === 'combo') {
    const cats = ctx.table(spec).categories, layers = spec.layers;
    const axisFields = axis => [...new Set(layers.filter(l => l.axis === axis).map(l => l.field))];
    const leftFields = axisFields('left'), rightFields = axisFields('right');
    const rowsByCategory = cats.map(c => data.find(r => r[enc.category] === c));
    const allValues = f => rowsByCategory.map(r => r?.[f]);
    const fieldsByAxis = { left: leftFields, right: rightFields };
    // 主轴先取整齐刻度，副轴按同一区间数取刻度：两侧刻度落在同一组网格线上，读数不会错位。
    const scales = {}, axisTicks = {};
    for (const axis of ['left', 'right']) {
      const names = fieldsByAxis[axis];
      if (!names.length) continue;
      const units = new Set(names.map(f => `${ctx.field(f).unit || ''}|${ctx.field(f).format || ''}`));
      if (units.size !== 1) ctx.fit(msg(`combo ${axis}轴的多个字段单位必须一致`, `Combo fields on the ${axis} axis must use matching units`), msg('统一字段单位与格式后重试', 'Use a consistent unit and format on the axis'));
      const baseline = layers.some(l => l.axis === axis && ['area', 'column'].includes(l.mark));
      const ranges = names.map(f => number(ctx, f, allValues(f), baseline));
      const annotations = (spec.annotations || []).filter(a => names.includes(a.field)).flatMap(a => a.kind === 'rule' ? [a.value] : a.kind === 'band' ? [a.from, a.to] : []);
      const min = Math.min(...ranges.map(r => r.min), ...annotations);
      const max = Math.max(...ranges.map(r => r.max), ...annotations);
      const primary = Object.values(axisTicks)[0];
      const nice = ctx.ticks([min, max], names[0], {
        zero: baseline, length: Math.max(120, width - 160), percentSymbol: false,
        ...(primary ? { intervals: primary.ticks.length - 1 } : {}),
      });
      axisTicks[axis] = nice;
      names.forEach(f => {
        scales[f] = nice;
      });
    }
    const leftGutter = Math.max(36, ...(axisTicks.left?.labels || ['0']).map(label => ctx.measure(label, 12))) + 16;
    const rightGutter = Math.max(28, ...(axisTicks.right?.labels || ['']).map(label => ctx.measure(label, 12))) + 16;
    const annotationRows = (spec.annotations || []).filter(annotation => annotation.label || annotation.text).length;
    const p = plot(36 + annotationRows * 16, 302, leftGutter, width - rightGutter);
    reserveEdgeCategories(cats, p);
    const yFor = (field, v) => p.y + p.h - (v - scales[field].min) / (scales[field].max - scales[field].min || 1) * p.h;
    const y0 = (field) => yFor(field, Math.max(scales[field].min, Math.min(scales[field].max, 0)));
    // 刻度只写数值，单位与所属轴由图例说明。
    const gridAxis = axisTicks.left || axisTicks.right;
    gridAxis.ticks.forEach((_, i) => {
      const y = p.y + p.h - i / (gridAxis.ticks.length - 1) * p.h;
      children.push(ctx.line(p.x, y, p.x + p.w, y, { stroke: ctx.color('grid') }));
      if (axisTicks.left) children.push(ctx.text(p.x - 8, y + 4, axisTicks.left.labels[i], { anchor: 'end', size: 12 }));
      if (axisTicks.right) children.push(ctx.text(p.x + p.w + 8, y + 4, axisTicks.right.labels[i], { size: 12 }));
    });
    children.push(ctx.line(p.x, p.y + p.h, p.x + p.w, p.y + p.h, { stroke: ctx.color('axis') }));
    const overColumns = layers.some(l => l.mark === 'column');
    layers.forEach((layer, li) => {
      const vals = allValues(layer.field), xs = cats.map((_, i) => bandX(i, cats.length, p)), ys = vals.map(v => finite(v) ? yFor(layer.field, v) : NaN), color = ctx.color(`tone${li % 6 + 1}`);
      if (layer.mark === 'column') {
        const group = layers.filter(l => l.mark === 'column' && l.axis === layer.axis), slot = group.indexOf(layer), bw = p.w / cats.length * .72 / group.length;
        vals.forEach((v, i) => {
          if (!finite(v)) return;
          const y = ys[i], base = y0(layer.field), left = xs[i] - bw * group.length / 2 + slot * bw;
          children.push(ctx.rect(left, Math.min(y, base), bw * .88, Math.max(1, Math.abs(base - y)), { fill: color }));
        });
      }
      if (layer.mark === 'area') {
        let segment = [];
        const close = () => {
          if (segment.length) {
            const base = y0(layer.field), pts = [...segment, [segment.at(-1)[0], base], [segment[0][0], base]];
            children.push(ctx.path(`${asPath(pts)} Z`, { fill: color, 'fill-opacity': .2, stroke: 'none' }));
            segment = [];
          }
        };
        vals.forEach((v, i) => {
          if (finite(v)) segment.push([xs[i], ys[i]]);
          else close();
        });
        close();
      }
      if (layer.mark === 'line' || layer.mark === 'area') {
        const d = linePath(vals, xs, v => yFor(layer.field, v));
        // 折线压在柱子上时先描一道底色边：暗色主题的浅色柱与浅色折线不会融在一起。
        if (overColumns) children.push(ctx.path(d, { fill: 'none', stroke: ctx.palette.bg, 'stroke-width': 5, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));
        children.push(ctx.path(d, { fill: 'none', stroke: color, 'stroke-width': 2 }));
        vals.forEach((v, i) => {
          if (finite(v)) children.push(ctx.circle(xs[i], ys[i], 2.6, { fill: color, ...(overColumns ? { stroke: ctx.palette.bg, 'stroke-width': 1.5 } : {}) }));
        });
      }
    });
    const comboNotes = [];
    for (const a of spec.annotations || []) {
      const layer = layers.find(l => l.field === a.field);
      if (a.kind === 'rule' && layer) {
        const y = yFor(a.field, a.value);
        children.push(ctx.line(p.x, y, p.x + p.w, y, { stroke: ctx.color('tone6'), 'stroke-dasharray': '4 3' }));
        if (a.label) comboNotes.push({ text: a.label, y: Math.max(p.y + 12, y - 16), anchor: 'start', x: p.x + 4, fill: ctx.textColor('fg') });
      }
      if (a.kind === 'band' && layer) {
        const y1 = yFor(a.field, a.from), y2 = yFor(a.field, a.to);
        children.push(ctx.rect(p.x, Math.min(y1, y2), p.w, Math.max(1, Math.abs(y2 - y1)), { fill: ctx.color('tone6'), 'fill-opacity': .12 }));
        if (a.label) comboNotes.push({ text: a.label, y: Math.min(y1, y2) + 14, anchor: 'end', fill: ctx.textColor('fg') });
      }
      if (a.kind === 'note' && enc.id) {
        const row = data.find(r => r[enc.id] === a.record), rowIndex = row ? cats.indexOf(row[enc.category]) : -1, layerForField = layers.find(l => l.field === a.field);
        if (rowIndex >= 0 && layerForField && finite(row[a.field])) comboNotes.push({ text: a.text, y: yFor(a.field, row[a.field]) - 12, anchor: 'end', fill: ctx.textColor('fg') });
      }
    }
    // 注释移入绘图区上方独立的页面底色行；每行间隔16px，避免填充影响对比度或撞到右轴刻度。
    comboNotes.sort((a, b) => a.y - b.y).forEach((item, index) => {
      const x = item.x ?? (item.anchor === 'end' ? p.x + p.w - 4 : p.x + 4);
      children.push(ctx.text(x, p.y - 8 - index * 16, item.text, { anchor: item.anchor, size: 12, ...(item.fill ? { fill: item.fill } : {}) }));
    });
    catLabels(cats, p);
    const lh = legend(layers.map((l, i) => {
      const meta = ctx.field(l.field), unit = meta.unit || (meta.format === 'percent' ? '%' : '');
      const axis = l.axis === 'right' ? msg('右轴', 'right axis') : msg('左轴', 'left axis');
      return { label: [meta.label, unit, axis].filter(Boolean).join(' · '), color: ctx.color(`tone${i % 6 + 1}`) };
    }), p.y + p.h + 36);
    const scene = endScene(p.y + p.h + 36 + lh);
    scene.width = Math.max(width, p.x + p.w + rightGutter);
    return scene;
  }

  if (spec.chart === 'bubble-matrix') {
    const rows = [...new Set(data.map(r => r[enc.row]))], cols = [...new Set(data.map(r => r[enc.column]))];
    const rd = ctx.field(enc.row).domain, cd = ctx.field(enc.column).domain;
    const rr = rd || rows, cc = cd || cols, vals = data.map(r => r[enc.value]), max = Math.max(0, ...vals);
    // 行名按实测宽度留列，超长才换行。列头与热力图共用规则：时间列压成月份、只在新年份标年，
    // 分类列按实测宽度加宽列槽，不把格子压到读数互相覆盖。
    const rowCap = Math.max(72, width * 0.28);
    const rowLines = rr.map(label => ctx.wrap(String(label), rowCap, 12));
    const rowWidth = Math.max(24, ...rowLines.flat().map(line => ctx.measure(line, 12)));
    const left = Math.min(rowCap, rowWidth) + 16;
    const headers = columnHeaders(ctx, cc, { left, right: 16, floor: 28 });
    const cellW = headers.slot;
    const cellH = Math.max(28, Math.floor(270 / Math.max(1, rr.length)));
    const chartWidth = Math.max(width, left + cc.length * cellW + 16);
    const gridH = rr.length * cellH;
    const p = { x: left, y: 28, w: cc.length * cellW, h: gridH };
    rr.forEach((label, i) => {
      const lines = ctx.wrap(String(label), rowWidth, 12);
      children.push(ctx.textLines(p.x - 8, p.y + (i + .5) * cellH + 4 - (lines.length - 1) * 8, lines, { anchor: 'end', size: 12 }));
    });
    const BUBBLE_OPACITY = .28;
    const bubbles = [];
    data.forEach(row => {
      const i = rr.indexOf(row[enc.row]), j = cc.indexOf(row[enc.column]), value = row[enc.value];
      if (i < 0 || j < 0) return;
      const x = p.x + (j + .5) * cellW, y = p.y + (i + .5) * cellH;
      const meta = { row: String(row[enc.row]), column: String(row[enc.column]), value };
      children.push(ctx.rect(p.x + j * cellW + 1, p.y + i * cellH + 1, cellW - 2, cellH - 2, { fill: ctx.color('grid') }));
      const radius = value > 0 ? Math.min(cellW, cellH) * .43 * Math.sqrt(value / (max || 1)) : 0;
      if (value > 0) {
        children.push(ctx.circle(x, y, radius, {
          fill: ctx.color('tone2'), 'fill-opacity': BUBBLE_OPACITY, stroke: ctx.color('tone2'), 'stroke-width': 1.5, meta,
        }));
      }
      bubbles.push({ x, y, radius, value, meta });
    });
    // 读数只画在自己的气泡里：跨过圆边和格线时一种字色无法同时满足两种底色。
    const readout = (value) => ctx.format(value, enc.value, false);
    const readoutColor = ctx.textOn('tone2', { opacity: BUBBLE_OPACITY, over: 'grid' });
    const readoutsFit = bubbles.every(item => {
      if (!(item.value > 0)) return true;
      const text = readout(item.value), textWidth = ctx.measure(text, 12);
      return textWidth + 4 <= item.radius * 2 && 12 <= item.radius * 1.6;
    });
    if (readoutsFit) bubbles.forEach(item => {
      if (!(item.value > 0)) return;
      children.push(ctx.text(item.x, item.y + 4, readout(item.value), {
        anchor: 'middle', size: 12, fill: readoutColor, meta: { ...item.meta, kind: 'cell-readout' },
      }));
    });
    const columnY = p.y + p.h + 18;
    const headerRows = Math.max(1, ...headers.items.map(item => item.lines.length));
    const yearY = columnY + headerRows * 16;
    headers.items.forEach((item, j) => {
      if (item.lines.length) children.push(ctx.textLines(p.x + (j + .5) * cellW, columnY, item.lines, { anchor: 'middle', size: 12 }));
      if (item.year) children.push(ctx.text(p.x + j * cellW, yearY, item.year, { size: 12, fill: ctx.color('muted') }));
    });
    const noteY = (headers.years ? yearY : yearY - 16) + 24;
    const rowLabel = ctx.field(enc.row).label, columnLabel = ctx.field(enc.column).label, valueLabel = ctx.field(enc.value).label;
    const noteLines = ctx.wrap(
      msg(`行：${rowLabel}；列：${columnLabel}；气泡面积 ∝ ${valueLabel}；0 = ${ctx.format(0, enc.value)}，最大 = ${ctx.format(max, enc.value)}`, `Rows: ${rowLabel}; columns: ${columnLabel}; bubble area ∝ ${valueLabel}; 0 = ${ctx.format(0, enc.value)}, max = ${ctx.format(max, enc.value)}`),
      Math.max(120, chartWidth - p.x - 24),
      12,
      400,
    );
    children.push(ctx.textLines(p.x, noteY, noteLines, { size: 12 }));
    const noteWidth = Math.max(...noteLines.map(line => ctx.measure(line, 12)));
    const scene = ctx.scene(noteY + noteLines.length * 16 + 12, children, title);
    scene.width = Math.max(chartWidth, p.x + noteWidth + 16);
    return scene;
  }

  if (spec.chart === 'calendar') {
    const dateAt = (y, month, day) => {
      const date = new Date(0);
      date.setUTCHours(0, 0, 0, 0);
      date.setUTCFullYear(y, month, day);
      return date;
    };
    const dateValues = data.map(row => String(row[enc.date] ?? '')).filter(value => /^\d{4}-\d{2}-\d{2}$/.test(value)).sort();
    if (!dateValues.length) ctx.fit(msg('日历需要有效日期', 'Calendar requires valid dates'), msg('提供 YYYY-MM-DD 格式的日期', 'Provide dates in YYYY-MM-DD format'));
    const [startYear, startMonth] = dateValues[0].split('-').map(Number);
    const [lastYear, lastMonth] = dateValues.at(-1).slice(0, 7).split('-').map(Number);
    const start = dateAt(startYear, startMonth - 1, 1), end = dateAt(lastYear, lastMonth, 0);
    const days = (end - start) / 86400000 + 1;
    if (days > 10000) ctx.fit(msg('日历日期跨度过长', 'Calendar date span is too long'), msg('缩小到 10000 天以内的日期范围', 'Limit the date range to 10000 days'));
    const firstDay = new Intl.Locale(ctx.lang).weekInfo?.firstDay || (/^en-US/i.test(ctx.lang) ? 7 : 1), offset = (start.getUTCDay() - firstDay + 7) % 7;
    const weeks = Math.ceil((offset + days) / 7);
    const weekDay = new Intl.DateTimeFormat(ctx.lang, { weekday: 'narrow', timeZone: 'UTC' });
    const daysLabel = Array.from({ length: 7 }, (_, i) => weekDay.format(dateAt(2023, 0, 1 + ((firstDay % 7 + i) % 7))));
    // 左侧只放单字星期名，按实测宽度留边，把横向空间让给格子。
    const side = { l: Math.max(...daysLabel.map(d => ctx.measure(d, 12))) + 16, r: 16 };
    // 先留固定格间距再定格子边长：格子之间始终有可见留白，不会拼成无缝棋盘。
    const slotWidth = (width - side.l - side.r) / weeks, gap = slotWidth >= 16 ? 3 : 2;
    const cell = Math.max(10, Math.min(22, Math.floor(slotWidth - gap))), step = cell + gap, corner = Math.min(3, cell * .2);
    const chartWidth = Math.max(width, side.l + weeks * step + side.r);
    // 顶部只留年份与月份两行标签的高度。
    const p = { x: side.l, y: 48, w: weeks * step, h: 7 * step };
    const values = new Map(data.map(r => [r[enc.date], r[enc.value]]));
    const nums = data.map(r => r[enc.value]);
    const negativeMax = Math.max(0, ...nums.filter(v => v < 0).map(v => Math.abs(v)));
    const positiveMax = Math.max(0, ...nums.filter(v => v > 0));
    daysLabel.forEach((d, i) => {
      if ([0, 2, 4].includes(i)) children.push(ctx.text(p.x - 8, p.y + i * step + cell * .68, d, { anchor: 'end', size: 12 }));
    });
    for (let d = 0; d < days; d++) {
      const dateObj = dateAt(startYear, startMonth - 1, d + 1), date = dateObj.toISOString().slice(0, 10);
      const index = offset + d, col = Math.floor(index / 7), row = index % 7, value = values.get(date);
      const x = p.x + col * step, y = p.y + row * step;
      const sideMax = value < 0 ? negativeMax : positiveMax;
      if (value == null) children.push(ctx.rect(x, y, cell, cell, { rx: corner, fill: 'none', stroke: ctx.color('axis'), 'stroke-dasharray': '2 2', meta: { record: date, value: null } }));
      else if (spec.variant === 'dots') {
        const radius = value === 0 ? 2.5 : 2.5 + (cell * .35 - 2.5) * Math.sqrt(Math.abs(value) / (sideMax || 1));
        children.push(ctx.circle(x + cell / 2, y + cell / 2, radius, {
          fill: value < 0 ? ctx.color('tone2') : ctx.color('tone1'),
          'fill-opacity': value === 0 ? .08 : .82,
          stroke: value === 0 ? ctx.color('axis') : 'none',
          meta: { record: date, value },
        }));
      } else {
        const ratio = value === 0 ? 0 : Math.abs(value) / (sideMax || 1);
        const base = value < 0 ? ctx.palette.tone2 : ctx.palette.tone1;
        children.push(ctx.rect(x, y, cell, cell, {
          rx: corner,
          fill: ctx.mix(ctx.palette.bg, base, value === 0 ? .12 : .2 + ratio * .7),
          stroke: value === 0 ? ctx.color('axis') : 'none',
          'stroke-width': value === 0 ? 1 : 0,
          meta: { record: date, value },
        }));
      }
    }
    const months = [];
    for (let year = startYear, month = startMonth; year < lastYear || year === lastYear && month <= lastMonth;) {
      months.push(`${year}-${String(month).padStart(2, '0')}`);
      month += 1;
      if (month > 12) { year += 1; month = 1; }
    }
    ctx.compactTemporal(months).forEach((item, i) => {
      const [year, month] = months[i].split('-').map(Number);
      const monthStart = dateAt(year, month - 1, 1);
      const col = Math.floor((offset + (monthStart - start) / 86400000) / 7);
      if (item.year) children.push(ctx.text(p.x + col * step, p.y - 26, item.year, { size: 12, fill: ctx.color('muted') }));
      children.push(ctx.text(p.x + col * step, p.y - 10, item.label, { size: 12, fill: ctx.color('muted') }));
    });
    const descriptionText = msg('未采集：虚线；零值：描边', 'Missing: dashed; zero: outlined');
    const ramps = [
      ...(positiveMax || !negativeMax ? [{ maximum: positiveMax, color: ctx.palette.tone1, negative: false }] : []),
      ...(negativeMax ? [{ maximum: negativeMax, color: ctx.palette.tone2, negative: true }] : []),
    ].map(ramp => ({
      ...ramp,
      label: spec.variant === 'dots'
        ? msg(ramp.negative ? '负值面积小→大' : '正值面积小→大', ramp.negative ? 'Negative area: small→large' : 'Positive area: small→large')
        : ramp.negative ? msg('负值色阶', 'Negative color scale')
          : negativeMax ? msg('正值色阶', 'Positive color scale') : msg('色阶', 'Color scale'),
    }));
    const legendBlockWidth = Math.max(ctx.measure(descriptionText, 12), ...ramps.map(ramp =>
      ctx.measure(ramp.label, 12) + 16 + 106 + ctx.measure(ctx.format(ramp.negative ? -ramp.maximum : ramp.maximum, enc.value), 12)));
    const sideLegend = p.x + p.w + 32 + legendBlockWidth <= chartWidth - side.r;
    const legendX = sideLegend ? p.x + p.w + 32 : p.x;
    let legendY = sideLegend ? p.y : p.y + p.h + 24;
    const availableLegendWidth = sideLegend ? chartWidth - side.r - legendX : chartWidth - p.x - side.r;
    const description = ctx.wrap(descriptionText, availableLegendWidth, 12);
    children.push(ctx.textLines(legendX, legendY + 12, description, { size: 12 }));
    legendY += description.length * 16 + 10;
    for (const ramp of ramps) {
      const labelLines = ctx.wrap(ramp.label, availableLegendWidth, 12);
      children.push(ctx.textLines(legendX, legendY + 12, labelLines, { size: 12 }));
      legendY += labelLines.length * 16 + 4;
      for (let i = 0; i < 5; i++) {
        const x = legendX + i * 22;
        if (spec.variant === 'dots') children.push(ctx.circle(x + 9, legendY + 5, 2.5 + i, { fill: ramp.color, 'fill-opacity': .82 }));
        else children.push(ctx.rect(x, legendY, 18, 10, { fill: ctx.mix(ctx.palette.bg, ramp.color, .2 + i / 4 * .7), stroke: ctx.color('axis'), 'stroke-width': .5 }));
      }
      children.push(ctx.text(legendX, legendY + 28, ctx.format(0, enc.value), { size: 12 }));
      children.push(ctx.text(legendX + 72, legendY + 28, ctx.format(ramp.negative ? -ramp.maximum : ramp.maximum, enc.value), { size: 12 }));
      legendY += 44;
    }
    if (sideLegend) legendY = Math.max(legendY, p.y + p.h + 24);
    const scene = ctx.scene(legendY + 8, children, title);
    scene.width = chartWidth;
    return scene;
  }

  if (spec.chart === 'tally') {
    const t = ctx.table(spec), columns = 10;
    // 横向每组至少放下两个汉字宽的标题；更窄就改成纵向。折行超过三行同样改纵向，避免一字一行。
    const minSlot = Math.max(64, ctx.measure('字字', 12, 600) + 16);
    const slot = width / Math.max(1, t.categories.length);
    const titleDepth = Math.max(...t.categories.map((category) => ctx.wrap(String(category), Math.max(24, slot - 12), 12, 600).length));
    const horizontal = width >= 520 && slot >= minSlot && titleDepth <= 3;
    const categoryWidth = Math.min(width * 0.35, Math.max(24,
      ...t.categories.map(c => ctx.measure(String(c), 12, 600))));
    const valueWidth = Math.max(40,
      ...t.series[0].values.map(v => ctx.measure(ctx.format(v, enc.value), 12, 600)));
    const pitch = horizontal
      ? Math.max(7, Math.min(12, (width - 32) / (t.categories.length * columns)))
      : Math.max(6, Math.min(9, (width - categoryWidth - valueWidth - 36) / columns));
    const dot = pitch * 0.7;
    if (horizontal) {
      const slotWidth = width / t.categories.length;
      const titles = t.categories.map((category) => ctx.wrap(String(category), Math.max(24, slotWidth - 12), 12, 600));
      const titleLines = Math.max(1, ...titles.map((lines) => lines.length));
      const gridTop = 28 + titleLines * 16;
      t.categories.forEach((category, i) => {
        const value = t.series[0].values[i], center = slotWidth * (i + 0.5);
        const categoryLines = titles[i];
        children.push(ctx.textLines(center, 16 + (titleLines - categoryLines.length) * 8, categoryLines, { anchor: 'middle', size: 12, weight: 600, fill: ctx.color('fg') }));
        const dotsX = center - (columns - 1) * pitch / 2;
        for (let n = 0; n < 100; n++) {
          const x = dotsX + (n % columns) * pitch, cy = gridTop + Math.floor(n / columns) * pitch;
          const portion = Math.max(0, Math.min(1, value * 100 - n));
          const radius = dot * (portion > 0 && portion < 1 ? 0.35 : 0.5);
          children.push(ctx.circle(x, cy, radius, {
            fill: portion ? ctx.color('tone1') : ctx.color('axis'), opacity: 1,
            meta: { kind: 'tally-mark', category, index: n, value, portion },
          }));
        }
        children.push(ctx.text(center, gridTop + 10 * pitch + 20, ctx.format(value, enc.value), { anchor: 'middle', size: 12, weight: 600, fill: ctx.color('fg') }));
      });
      const note = ctx.wrap(msg('每项独立百分比；点阵总量不要求相加为100%', 'Independent percentages; dot totals need not sum to 100%'), width - 32, 12);
      const noteY = gridTop + 10 * pitch + 52;
      children.push(ctx.textLines(16, noteY, note, { size: 12 }));
      return ctx.scene(noteY + note.length * 16 + 12, children, title);
    }
    const groupWidth = categoryWidth + 8 + columns * pitch + 12 + valueWidth;
    const chartWidth = Math.max(width, groupWidth + 16);
    const labelX = (chartWidth - groupWidth) / 2, dotsX = labelX + categoryWidth + 8;
    const valueX = dotsX + columns * pitch + 12 + valueWidth;
    const categoryLines = t.categories.map((category) => ctx.wrap(String(category), categoryWidth, 12, 600));
    const rowHeights = categoryLines.map((lines) => Math.max(columns * pitch + 16, lines.length * 16 + 12));
    let cursor = 24;
    t.categories.forEach((category, i) => {
      const value = t.series[0].values[i], rowH = rowHeights[i], y = cursor + rowH / 2;
      children.push(ctx.textLines(labelX, y + 4 - (categoryLines[i].length - 1) * 8, categoryLines[i], { size: 12, weight: 600, fill: ctx.color('fg') }));
      for (let n = 0; n < 100; n++) {
        const x = dotsX + (n % columns) * pitch, cy = y - 22 + Math.floor(n / columns) * pitch;
        const portion = Math.max(0, Math.min(1, value * 100 - n));
        const radius = dot * (portion > 0 && portion < 1 ? 0.35 : 0.5);
        children.push(ctx.circle(x, cy, radius, {
          fill: portion ? ctx.color('tone1') : ctx.color('axis'), opacity: 1,
          meta: { kind: 'tally-mark', category, index: n, value, portion },
        }));
      }
      children.push(ctx.text(valueX, y + 4, ctx.format(value, enc.value), { anchor: 'end', size: 12, weight: 600, fill: ctx.color('fg') }));
      cursor += rowH;
    });
    const note = ctx.wrap(msg('每项独立百分比；点阵总量不要求相加为100%', 'Independent percentages; dot totals need not sum to 100%'), chartWidth - labelX - 16, 12);
    const dotBottom = cursor - rowHeights.at(-1) / 2 - 22 + (columns - 1) * pitch + dot / 2;
    const noteY = Math.max(cursor + 20, dotBottom + 28);
    children.push(ctx.textLines(labelX, noteY, note, { size: 12 }));
    const scene = ctx.scene(noteY + note.length * 16 + 12, children, title);
    scene.width = chartWidth;
    return scene;
  }

  if (spec.chart === 'bump') {
    const categories = ctx.field(enc.category).domain || [...new Set(data.map(r => r[enc.category]))];
    const series = [...new Set(data.map(r => r[enc.series]))];
    const ranks = data.map(r => r[enc.rank]).filter(finite), max = Math.max(...ranks);
    // 系列名按实测宽度换行，最多两行；放不下就加宽场景，不按画布比例截断。
    const LINE = 16;
    const capOf = (label) => {
      const full = ctx.measure(String(label), 12);
      // Halving the width may cut a Latin word in two; the cap is never narrower than the widest word.
      const word = Math.max(0, ...(String(label).match(/[A-Za-z0-9’'.-]+/g) || []).map(part => ctx.measure(part, 12)));
      let cap = Math.min(160, Math.max(48, Math.ceil(full / 2), Math.ceil(word)));
      let lines = ctx.wrap(String(label), cap, 12);
      while (lines.length > 2) {
        cap += 12;
        lines = ctx.wrap(String(label), cap, 12);
      }
      return lines;
    };
    const nameLines = series.map(capOf);
    const nameColumn = Math.max(24, ...nameLines.flat().map(line => ctx.measure(line, 12)));
    // 两端都留系列名：超过 6 色后颜色会循环，只靠右端和点色分不清。
    const rankColumn = 28;
    const left = 8 + nameColumn + 8 + rankColumn;
    const rightReserve = nameColumn + 16;
    const minPlotWidth = Math.max(1, categories.length) * 36;
    const chartWidth = Math.max(width, left + minPlotWidth + rightReserve);
    const rowSpan = Math.max(36, ...nameLines.map(lines => lines.length * LINE + 4));
    const plotHeight = Math.max(220, (Math.max(1, max) - 1) * rowSpan);
    const p = plot(48, 48 + plotHeight, left, chartWidth - rightReserve);
    const xs = categories.map((_, i) => bandX(i, categories.length, p));
    const yOf = (rank) => p.y + (rank - 1) / Math.max(1, max - 1) * p.h;
    for (let rank = 1; rank <= max; rank++) {
      const y = yOf(rank);
      children.push(ctx.line(p.x, y, p.x + p.w, y, { stroke: ctx.color('grid') }));
      children.push(ctx.text(p.x - 8, y + 4, String(rank), { anchor: 'end', size: 12 }));
    }
    const placed = { start: [], end: [] };
    const dodge = (side, y, lines) => {
      const height = lines.length * LINE;
      let top = y - 14;
      const lane = placed[side];
      for (let guard = 0; guard < series.length + 2; guard += 1) {
        const hit = lane.find(item => top < item.bottom + 4 && top + height > item.top);
        if (!hit) break;
        top = hit.bottom + 4;
      }
      lane.push({ top, bottom: top + height });
      return top + 12;
    };
    series.forEach((id, j) => {
      const rows = categories.map(c => data.find(r => r[enc.category] === c && r[enc.series] === id));
      const tone = `tone${j % 6 + 1}`, color = ctx.color(tone), labelColor = ctx.textColor(tone);
      const values = rows.map(r => r?.[enc.rank] ?? null);
      children.push(ctx.path(linePath(values, xs, v => yOf(v)), { fill: 'none', stroke: color, 'stroke-width': 2 }));
      const lines = ctx.wrap(String(id), nameColumn, 12);
      values.forEach((v, i) => {
        if (!finite(v)) return;
        const tied = data.filter(r => r[enc.category] === categories[i] && r[enc.rank] === v);
        const tieIndex = tied.findIndex(r => r[enc.series] === id);
        const offset = tied.length > 1 ? (tieIndex - (tied.length - 1) / 2) * 12 : 0;
        const x = xs[i] + offset, y = yOf(v) + offset;
        const meta = { record: rows[i]?.[enc.id] || String(id), series: id, category: categories[i], rank: v };
        children.push(ctx.circle(x, y, 5, { fill: color, stroke: ctx.color('bg'), 'stroke-width': 1.5, meta }));
        if (i === 0) children.push(ctx.textLines(p.x - rankColumn, dodge('end', y, lines), lines, { anchor: 'end', size: 12, fill: labelColor, leading: LINE, meta }));
        if (i === categories.length - 1) children.push(ctx.textLines(p.x + p.w + 8, dodge('start', y, lines), lines, { anchor: 'start', size: 12, fill: labelColor, leading: LINE, meta }));
      });
    });
    const nameBottom = Math.max(p.y + p.h, ...placed.start.map(item => item.bottom), ...placed.end.map(item => item.bottom));
    catLabels(categories, p, nameBottom + 20);
    const scene = ctx.scene(nameBottom + 40, children, title);
    scene.width = chartWidth;
    return scene;
  }

  if (spec.chart === 'radar') {
    const dimensions = enc.dimensions, domains = dimensions.map(field => ctx.field(field).domain);
    const angles = dimensions.map((_, i) => -Math.PI / 2 + i * Math.PI * 2 / dimensions.length);
    // 范围只写一次单位：两端都带单位会变成「0个–435.8个」。
    const rangeText = (field, domain) => {
      const meta = ctx.field(field);
      const bare = ctx.format(domain[0], field, false);
      const full = ctx.format(domain[1], field, true);
      return meta.unit || meta.format === 'percent' ? `${bare}–${full}` : `${ctx.format(domain[0], field)}–${full}`;
    };
    const axisLabels = dimensions.map((field, i) => ({
      name: String(ctx.field(field).label),
      range: rangeText(field, domains[i]),
    }));
    // 换行宽度取相邻轴在标签半径上的弦长，长轴名折进自己的扇区，不再压到邻轴。
    const chord = 2 * Math.sin(Math.PI / dimensions.length);
    const labelRoom = dimensions.length >= 6
      ? Math.max(48, Math.min(96, Math.ceil(width * chord * 0.42)))
      : Math.max(84, Math.min(140, Math.ceil(Math.max(72, width * 0.2) * chord)));
    const wrapped = axisLabels.map(item => ({
      name: ctx.wrap(item.name, labelRoom, 12, 600),
      range: ctx.wrap(item.range, labelRoom, 12, 400),
    }));
    const textWidth = Math.max(0, ...wrapped.flatMap(item => [
      ...item.name.map(line => ctx.measure(line, 12, 600)),
      ...item.range.map(line => ctx.measure(line, 12, 400)),
    ]));
    const labelDepth = Math.max(...wrapped.map(item => (item.name.length + item.range.length) * 16));
    const radius = Math.min(180, Math.max(72, (width - textWidth * 2 - 24) / 2));
    const cx = Math.max(width / 2, textWidth + radius + 12);
    const cy = radius + labelDepth + 24;
    const chartWidth = Math.max(width, cx + radius + textWidth + 12);
    const radiusAt = (axis, value) => {
      const [lo, hi] = domains[axis];
      return Math.max(0, Math.min(1, (value - lo) / (hi - lo || 1))) * radius;
    };
    for (let ring = 1; ring <= 4; ring++) {
      const points = angles.map(angle => [cx + Math.cos(angle) * radius * ring / 4, cy + Math.sin(angle) * radius * ring / 4]);
      children.push(ctx.el('polygon', {
        points: points.map(point => point.join(',')).join(' '), fill: 'none', stroke: ctx.color('grid'),
      }));
    }
    angles.forEach((angle, i) => {
      const cos = Math.cos(angle), sin = Math.sin(angle);
      children.push(ctx.line(cx, cy, cx + cos * radius, cy + sin * radius, { stroke: ctx.color('axis') }));
      const horizontal = Math.abs(cos) >= Math.abs(sin);
      const anchor = horizontal ? (cos < 0 ? 'end' : 'start') : 'middle';
      const tx = horizontal ? cx + cos * (radius + 10) : cx + cos * radius;
      const ty = horizontal ? cy + sin * radius : cy + sin * (radius + 10);
      const block = wrapped[i].name.length + wrapped[i].range.length;
      const firstY = horizontal ? ty - (block - 1) * 8 : sin < 0 ? ty - block * 16 - 4 : ty + 16;
      children.push(ctx.textLines(tx, firstY, wrapped[i].name, { anchor, size: 12, weight: 600, fill: ctx.color('fg') }));
      children.push(ctx.textLines(tx, firstY + wrapped[i].name.length * 16, wrapped[i].range, { anchor, size: 12, weight: 400, fill: ctx.color('muted') }));
    });
    data.forEach((row, rowIndex) => {
      const points = dimensions.map((field, i) => [
        cx + Math.cos(angles[i]) * radiusAt(i, row[field]),
        cy + Math.sin(angles[i]) * radiusAt(i, row[field]),
      ]);
      const color = ctx.color(`tone${rowIndex % 6 + 1}`);
      children.push(ctx.el('polygon', {
        points: points.map(point => point.join(',')).join(' '), fill: color, 'fill-opacity': .14, stroke: color, 'stroke-width': 2,
      }));
      points.forEach((point, i) => children.push(ctx.circle(point[0], point[1], 3, {
        fill: color, meta: { record: row[enc.id] || String(rowIndex), field: dimensions[i], value: row[dimensions[i]] },
      })));
    });
    const legendY = cy + radius + labelDepth + 12;
    const legendItems = data.map((row, i) => ({
      label: row[enc.label], color: ctx.color(`tone${i % 6 + 1}`), meta: { record: row[enc.id] || String(i) },
    }));
    const legendBlock = ctx.legend(legendItems, Math.max(120, chartWidth - 32));
    children.push(ctx.el('g', { transform: `translate(16,${legendY})` }, legendBlock.children));
    const scene = ctx.scene(legendY + legendBlock.height + 16, children, title);
    scene.width = chartWidth;
    return scene;
  }

  if (spec.chart === 'parallel') {
    const dimensions = enc.dimensions;
    const domainFor = (f) => ctx.field(f).domain || (() => {
      const e = ctx.extent(data.map(r => r[f]).filter(finite));
      return e[0] === e[1] ? [e[0] - 1, e[1] + 1] : e;
    })();
    const axisTitle = (f) => {
      const meta = ctx.field(f);
      const unit = meta.unit || (meta.format === 'percent' ? '%' : '');
      return [meta.label, unit].filter(Boolean).join(' · ');
    };
    // 轴名换行宽度不超过相邻轴距，首尾轴名才不会画出场景或盖住邻轴。
    const titleLines = (slot) => dimensions.map(f => ctx.wrap(axisTitle(f), Math.max(36, slot - 12), 12, 600));
    const tickLabel = (f, value) => ctx.format(value, f, false);
    const tickWidth = Math.max(0, ...dimensions.flatMap(f => {
      const domain = domainFor(f);
      return [0, 0.5, 1].map(step => ctx.measure(tickLabel(f, domain[0] + (domain[1] - domain[0]) * step), 12));
    }));
    const titleWidth = Math.max(0, ...dimensions.map(f => ctx.measure(axisTitle(f), 12, 600)));
    const side = Math.ceil(Math.max(tickWidth, titleWidth) / 2) + 8;
    const minSlot = Math.max(48, tickWidth + 8, ...titleLines(72).map(lines => Math.max(...lines.map(line => ctx.measure(line, 12, 600))) + 12));
    const gaps = Math.max(1, dimensions.length - 1);
    const slot = Math.max(minSlot, Math.floor((width - side * 2) / gaps));
    const chartWidth = Math.max(width, side + gaps * slot + side);
    const head = titleLines(slot);
    const headHeight = Math.max(...head.map(lines => lines.length)) * 16 + 4;
    const p = plot(headHeight + 20, headHeight + 248, side, chartWidth - side);
    const xs = dimensions.map((_, i) => dimensions.length === 1 ? (p.x + p.w / 2) : p.x + i * slot);
    dimensions.forEach((f, i) => {
      const d = domainFor(f);
      children.push(ctx.line(xs[i], p.y, xs[i], p.y + p.h, { stroke: ctx.color('axis') }));
      for (let k = 0; k <= 4; k++) {
        const v = d[0] + (d[1] - d[0]) * k / 4, y = p.y + p.h - k * p.h / 4;
        children.push(ctx.line(xs[i] - 3, y, xs[i] + 3, y, { stroke: ctx.color('axis') }));
        // 单位已经写在轴名上，刻度只保留数字，避免「227.8万万元」。
        if (k === 0 || k === 4 || k === 2) children.push(ctx.text(xs[i], y - 4, tickLabel(f, v), { anchor: 'middle', size: 12 }));
      }
      children.push(ctx.textLines(xs[i], 16, head[i], { anchor: 'middle', size: 12, weight: 600, fill: ctx.color('fg') }));
    });
    data.forEach((row, ri) => {
      const values = dimensions.map(f => finite(row[f]) ? row[f] : null);
      const ys = values.map((v, i) => v === null
        ? NaN
        : p.y + p.h - (v - domainFor(dimensions[i])[0]) / (domainFor(dimensions[i])[1] - domainFor(dimensions[i])[0]) * p.h);
      const color = ctx.color(`tone${ri % 6 + 1}`);
      children.push(ctx.path(linePath(values, xs, (_, i) => ys[i]), {
        fill: 'none',
        stroke: color,
        'stroke-width': 1.6,
        'stroke-opacity': .72,
        meta: { record: row[enc.id] || String(ri), series: row[enc.series] },
      }));
    });
    const legendY = p.y + p.h + 28;
    const legendItems = data.map((r, i) => ({ label: String(r[enc.label]), color: ctx.color(`tone${i % 6 + 1}`), meta: { record: r[enc.id] || String(i) } }));
    const legendBlock = ctx.legend(legendItems, Math.max(120, chartWidth - 32));
    children.push(ctx.el('g', { transform: `translate(16,${legendY})` }, legendBlock.children));
    const scene = ctx.scene(legendY + legendBlock.height + 16, children, title);
    scene.width = chartWidth;
    return scene;
  }

  if (spec.chart === 'launch-fan') {
    const starts = data.map(r => r[enc.start]), values = data.map(r => r[enc.value]);
    // 扇形没有纵轴，左右只留版心边距，把宽度留给时间范围和末端标签。
    const side = 16;
    const max = Math.max(1, ...values), p = plot(78, 320, side, width - side);
    const sameType = starts.every(v => typeof v === typeof starts[0]);
    if (!sameType) ctx.fit(msg('launch-fan起点类型不一致', 'launch-fan start types differ'), msg('统一使用数值时点或同一时间类型后重试', 'Use numeric starts or a consistent date type'));
    const dates = typeof starts[0] === 'string';
    const nums = starts.map(v => dates ? Date.parse(v) : v);
    const labels = data.map((row, i) => `${row[enc.label]} · ${ctx.format(values[i], enc.value)}`);
    const labelWidth = Math.min(width * 0.27, Math.max(52, ...labels.map(label => ctx.measure(label, 12, 400))));
    const labelLines = labels.map(label => ctx.wrap(label, labelWidth, 12));
    // 末端标签始终在圆右侧：先为标签列和最大圆留位，再把剩余宽度给扇形；扇形过窄时整体加宽。
    const labelColumn = Math.max(...labelLines.map(lines => Math.max(...lines.map(line => ctx.measure(line, 12)))));
    const maxRadius = 28, fanMin = 128;
    const endX = Math.max(p.x + fanMin, Math.min(p.x + p.w * .84, width - side - labelColumn - maxRadius - 8));
    const chartWidth = Math.max(width, endX + maxRadius + 8 + labelColumn + side);
    const lo = Math.min(...nums), hi = Math.max(...nums);
    // 时间轴止于末端圆列之前，最晚起点的弧线也有可见长度。
    const timeEnd = endX - maxRadius - 16;
    const x = ctx.linear(lo, hi || lo + 1, p.x + 10, timeEnd);
    const sorted = data.map((row, i) => ({ row, i, start: nums[i] })).sort((a, b) => a.start - b.start || a.i - b.i);
    // 相邻两行的末端圆不能相交：行距至少容下上下两个圆的半径之和。
    const radiusOf = i => Math.sqrt(values[i] / max) * maxRadius;
    const circleGap = Math.max(0, ...sorted.slice(1).map((item, k) => radiusOf(sorted[k].i) + radiusOf(item.i) + 6));
    const rowGap = Math.max(36, circleGap, ...labelLines.map(lines => lines.length * 16 + 8));
    const fanHeight = Math.max(p.h, maxRadius * 2 + 6 + Math.max(0, data.length - 1) * rowGap);
    const baseline = p.y + fanHeight;
    // 末端圆整体位于基线上方，不压到基线和日期刻度。
    const bubbleTop = p.y + maxRadius, bubbleBottom = baseline - maxRadius - 6;
    children.push(ctx.line(p.x, baseline, timeEnd + 10, baseline, { stroke: ctx.color('axis') }));
    const startClusters = [];
    sorted.forEach(item => {
      const sx = x(item.start), cluster = startClusters.at(-1);
      if (!cluster || sx - cluster.x >= 7) startClusters.push({ x: sx, items: [item] });
      else cluster.items.push(item);
    });
    const startOffset = new Map();
    startClusters.forEach(cluster => {
      cluster.items.forEach((item, index) => {
        startOffset.set(item.i, (index - (cluster.items.length - 1) / 2) * 7);
      });
    });
    sorted.forEach(({ row, i, start }, rank) => {
      const sx = x(start), startY = baseline + startOffset.get(i);
      const ey = bubbleTop + rank * (bubbleBottom - bubbleTop) / Math.max(1, data.length - 1);
      const radius = Math.sqrt(values[i] / max) * maxRadius;
      const color = ctx.color(`tone${i % 6 + 1}`), id = row[enc.id] || String(i);
      // 弧线止于圆的左缘，不在半透明圆内留下一截线头。
      children.push(ctx.path(`M${sx},${startY} Q${(sx + endX) / 2},${ey} ${endX - radius},${ey}`, { fill: 'none', stroke: color, 'stroke-width': Math.max(1, Math.sqrt(values[i] / max) * 3), 'stroke-opacity': .6 }));
      children.push(ctx.circle(sx, startY, 3, { fill: color, meta: { record: id, start } }));
      children.push(ctx.circle(endX, ey, radius, { fill: color, 'fill-opacity': .32, stroke: color, 'stroke-width': 1.5, meta: { record: id, value: values[i] } }));
      const lines = labelLines[i], labelY = ey - (lines.length - 1) * 8 + 4;
      children.push(ctx.textLines(endX + radius + 8, labelY, lines, { size: 12, fill: ctx.color('fg'), meta: { record: id, value: values[i] } }));
    });
    const timeLabel = (value, includeYear) => {
      if (!dates) return ctx.format(value, enc.start);
      const raw = String(starts.find(item => (typeof item === 'string' ? Date.parse(item) : item) === value));
      const monthOnly = /^\d{4}-\d{2}$/.test(raw);
      const options = { month: 'short', timeZone: 'UTC' };
      if (!monthOnly) options.day = 'numeric';
      if (includeYear) options.year = 'numeric';
      return new Intl.DateTimeFormat(ctx.lang, options).format(new Date(value));
    };
    const timeline = [...new Set(nums)].sort((a, b) => a - b).map(value => ({
      value, year: dates ? new Date(value).getUTCFullYear() : null,
    }));
    const withLabels = items => items.map((item, index) => ({
      ...item,
      label: timeLabel(item.value, dates && (index === 0 || item.year !== items[index - 1].year)),
    }));
    const labelPosition = item => x(item.value);
    // 末个日期在基线下方仍有右侧标签列的空位：放得下时从刻度向右展开，放不下才右对齐到刻度。
    const fitsRight = item => labelPosition(item) + ctx.measure(item.label, 12) <= chartWidth - side;
    const labelAnchor = (item, index, count = timeline.length) => {
      if (index === 0) return 'start';
      if (index === count - 1) return fitsRight(item) ? 'start' : 'end';
      return 'middle';
    };
    const labelBounds = (item, index, count) => {
      const center = labelPosition(item), textWidth = ctx.measure(item.label, 12), anchor = labelAnchor(item, index, count);
      return [anchor === 'start' ? center : anchor === 'end' ? center - textWidth : center - textWidth / 2,
        anchor === 'start' ? center + textWidth : anchor === 'end' ? center : center + textWidth / 2];
    };
    let selected = [];
    timeline.forEach((item, index) => {
      const candidate = withLabels([...selected.map(entry => ({ value: entry.value, year: entry.year })), item]);
      const clear = candidate.every((entry, at) => at === 0 || labelBounds(candidate[at - 1], at - 1, candidate.length)[1] + 8 <= labelBounds(entry, at, candidate.length)[0]);
      const last = index === timeline.length - 1;
      if (!clear && last && candidate.length > 2) candidate.splice(-2, 1);
      const kept = withLabels(candidate.map(entry => ({ value: entry.value, year: entry.year })));
      const keptClear = kept.every((entry, at) => at === 0 || labelBounds(kept[at - 1], at - 1, kept.length)[1] + 8 <= labelBounds(entry, at, kept.length)[0]);
      if ((clear || last) && keptClear) selected = kept;
    });
    selected.forEach((item, index) => {
      const at = labelPosition(item), anchor = labelAnchor(item, index, selected.length);
      children.push(ctx.line(at, baseline - 1, at, baseline + 5, { stroke: ctx.color('axis') }));
      children.push(ctx.text(at, baseline + 22, item.label, { anchor, size: 12, fill: ctx.color('muted'), meta: { kind: 'launch-fan-time', value: item.value } }));
    });
    const noteY = baseline + 50;
    const noteLines = ctx.wrap(msg('起点 = 开始时点；末端圆面积 = 当前量', 'Start = launch date; end-circle area = current value'), chartWidth - p.x - 16, 12);
    children.push(ctx.textLines(p.x, noteY, noteLines, { size: 12 }));
    const scene = ctx.scene(noteY + noteLines.length * 16 + 12, children, title);
    scene.width = chartWidth;
    return scene;
  }
  throw new Error(`Unsupported multivariate chart: ${spec.chart}`);
};

// Registers into the caller's registry so a Node build can assemble an isolated subset.
export function install({ register }) {
  register(['stream', 'split-compare', 'combo', 'bubble-matrix', 'calendar', 'tally', 'bump', 'radar', 'parallel', 'launch-fan'], chart);
}

install({ register });

/* Deterministic tree layouts shared by the mindmap and tree chart families. */

import { register } from './registry.js';
import { statusMarks } from '../core/theme.js';

const GAP_X = 44, COMPACT_GAP = 24, GAP_Y = 18, PAD_X = 14, PAD_Y = 9, TEXT_WIDTH = 220, MARGIN = 24;
// 排版方案从宽松到紧凑：先收窄节点换行宽度（不低于 120px 可读下限），再收紧层距。
// 取第一个放得进图框的方案；都放不下时用最紧凑的一档，保留所选布局，由宿主提供图内滚动。
const PLANS = [GAP_X, COMPACT_GAP].flatMap(gap => [TEXT_WIDTH, 190, 160, 140, 120].map(cap => ({ gap, cap })));
const mindLayouts = ['bilateral', 'right', 'left', 'radial', 'org', 'brace', 'fishbone', 'timeline'];
const treeLayouts = ['right', 'left', 'org', 'brace'];
const LEAF_LINE_GAP = 8;
const BRANCH_RADIUS = 7;
const hasFrame = (variant, depth, children) => depth === 0 || Boolean(children?.length) || variant === 'cards';
const nodeTextX = (box, alignRight) => alignRight ? box.x + box.w - PAD_X : box.x + PAD_X;

/** 按节点换行上限 cap 与层距 gap 排出整棵树，返回已平移到正坐标的节点框与内容宽度。 */
function arrange(spec, ctx, mode, { cap, gap }) {
  const nodes = [];
  const textWidth = cap - PAD_X * 2;
  function visit(source, parent = null, depth = 0) {
    if (source.icon) ctx.fit('此布局不支持节点图标', '删掉节点的 icon，保留文字标签');
    const weight = depth === 0 ? 650 : 500;
    const textOnly = mode === 'bilateral' && !hasFrame(spec.variant, depth, source.children);
    const wrapOptions = { bounded: textOnly };
    const marker = source.status ? statusMarks[source.status] : '';
    const markerWidth = marker ? ctx.measure(marker, 12, 700) + 6 : 0;
    const lines = ctx.wrap(source.label, textWidth - markerWidth, 13, weight, wrapOptions);
    const noteLines = source.note ? ctx.wrap(source.note, textWidth, 12, 400, wrapOptions) : [];
    const widths = [...lines.map(s => ctx.measure(s, 13, weight)), ...noteLines.map(s => ctx.measure(s, 12, 400))];
    const measuredWidth = Math.max(...widths) + PAD_X * 2 + markerWidth;
    const n = {
      id: source.id || `n${nodes.length}`, label: source.label, note: source.note || '', status: source.status || '', marker, markerWidth, parent, depth, children: [], lines, noteLines,
      w: Math.max(70, textOnly ? measuredWidth : Math.min(cap, measuredWidth)), contentW: measuredWidth - PAD_X * 2,
      h: Math.max(34, lines.length * 17 + noteLines.length * 15 + PAD_Y * 2),
    };
    nodes.push(n);
    n.children = (source.children || []).map(child => visit(child, n, depth + 1));
    return n;
  }
  const root = visit(spec.data);
  const leaves = n => n.children.length ? n.children.reduce((sum, c) => sum + leaves(c), 0) : 1;
  const maxDepth = Math.max(...nodes.map(n => n.depth));
  const maxH = Math.max(...nodes.map(n => n.h));
  const pitch = maxH + GAP_Y;
  const coords = new Map(), fishboneSpine = new Map();
  let fishboneSpineEnd = 0;
  const place = (n, x, y) => coords.set(n, { x, y, cx: x + n.w / 2, cy: y + n.h / 2, w: n.w, h: n.h });
  const levelWidths = group => Array.from({ length: maxDepth + 1 }, (_, d) => Math.max(0, ...group.filter(n => n.depth === d).map(n => n.w)));
  // 纵向按叶子数分配跨度，父节点居中于自己的子树；横坐标由各布局的列规则给出。
  const stack = (node, top, xOf) => {
    place(node, xOf(node), top + leaves(node) * pitch / 2 - node.h / 2);
    let at = top;
    for (const child of node.children) {
      stack(child, at, xOf);
      at += leaves(child) * pitch;
    }
  };
  if (mode === 'right' || mode === 'left' || mode === 'brace') {
    const levelW = levelWidths(nodes), col = [0];
    for (let d = 0; d < maxDepth; d++) col[d + 1] = col[d] + levelW[d] + gap;
    stack(root, 0, n => mode === 'left' ? -col[n.depth] - n.w : col[n.depth]);
  } else if (mode === 'bilateral') {
    // 一级分支按叶子数交替分到左右两侧；每侧逐层取该侧最宽节点定列宽，根与各层之间都相隔 gap。
    const sides = [[], []], mass = [0, 0];
    for (const child of root.children) {
      const side = mass[0] <= mass[1] ? 0 : 1;
      sides[side].push(child);
      mass[side] += leaves(child);
    }
    const subtree = n => [n, ...n.children.flatMap(subtree)];
    place(root, 0, -root.h / 2);
    sides.forEach((group, side) => {
      const levelW = levelWidths(group.flatMap(subtree)), start = [0, gap];
      for (let d = 1; d < maxDepth; d++) start[d + 1] = start[d] + levelW[d] + gap;
      let at = -mass[side] * pitch / 2;
      for (const node of group) {
        stack(node, at, n => side === 0 ? -start[n.depth] - n.w : root.w + start[n.depth]);
        at += leaves(node) * pitch;
      }
    });
  } else if (mode === 'org' || mode === 'timeline') {
    // Width each subtree from measured node widths; parent centered over source-order children.
    const subW = new Map();
