const path = (ctx, d, attrs = {}, meta) => ({ ...ctx.path(d, attrs), ...(meta ? { meta } : {}) });
const text = (ctx, x, y, value, opts, meta) => ctx.text(x, y, value, { 'dominant-baseline': 'central', ...opts, meta });
const group = (ctx, children, meta, attrs = {}) => ({ ...ctx.el('g', attrs, children), ...(meta ? { meta } : {}) });
const titleNode = (ctx, value) => value ? { ...ctx.el('title'), text: String(value) } : null;
const points = (coords) => coords.map(([x, y]) => `${x},${y}`).join(' ');

function defs(ctx, a) {
  const arrow = (id, color) => ({
    tag: 'marker', attrs: {
      id, viewBox: '0 0 8 8', refX: 8, refY: 4,
      markerWidth: 8, markerHeight: 8, markerUnits: 'userSpaceOnUse', orient: 'auto-start-reverse',
    }, children: [ctx.path('M0 0 L8 4 L0 8 Z', { fill: color })],
  });
  // From the relationship line toward the entity: minimum first, then maximum.
  // The outer circle/bar and the inner crow’s foot must occupy separate parts of the 16px stub.
  const zero = ['circle', 4, 8, 3], minOne = ['line', 'M4 2 V14'];
  const maxOne = ['line', 'M12 2 V14'], many = ['line', 'M15 2 L9 8 L15 14 M9 8 H15'];
  const cardSpecs = {
    'zero-one': [zero, maxOne], 'exactly-one': [minOne, maxOne],
    'zero-many': [zero, many], 'one-many': [minOne, many],
  };
  const cards = Object.entries(cardSpecs).map(([name, shapes]) => ({
    tag: 'marker', attrs: {
      id: `graph-card-${name}`, viewBox: '0 0 16 16', refX: 16, refY: 8,
      markerWidth: 16, markerHeight: 16, markerUnits: 'userSpaceOnUse', orient: 'auto-start-reverse',
    },
    children: shapes.map(([kind, ...args]) => kind === 'circle'
      ? ctx.circle(...args, { fill: a.surface, stroke: a.fg4, 'stroke-width': 1.4 })
      : ctx.path(args[0], { fill: 'none', stroke: a.fg4, 'stroke-width': 1.4 })),
  }));
  return ctx.el('defs', {}, [
    arrow('graph-arrow', a.fg4), arrow('graph-arrow-bold', a.fg3), ...cards,
  ]);
}

function cardKey(card) {
  return card === '|o' || card === 'o|' ? 'zero-one'
    : card === '||' ? 'exactly-one'
      : card === '}o' || card === 'o{' ? 'zero-many'
        : card === '}|' || card === '|{' ? 'one-many' : null;
}

function edgePath(edge, modelNodes, ctx, a) {
  if (!edge.segments?.length) return null;
  const d = cubicPath(edge.segments);
  const isEr = modelNodes.get(edge.from)?.kind === 'er' || modelNodes.get(edge.to)?.kind === 'er';
  const bold = edge.style === 'bold';
  const attrs = {
    fill: 'none', stroke: bold ? a.fg3 : a.fg4, 'stroke-width': bold ? 2 : 1.25,
    ...(edge.style === 'dashed' ? { 'stroke-dasharray': '5 4' } : {}),
  };
  if (isEr) {
    const start = edge.startCard && cardKey(edge.startCard), end = edge.endCard && cardKey(edge.endCard);
    if (start) attrs['marker-start'] = `url(#graph-card-${start})`;
    if (end) attrs['marker-end'] = `url(#graph-card-${end})`;
  } else {
    if (edge.startArrow) attrs['marker-start'] = `url(#graph-arrow${bold ? '-bold' : ''})`;
    if (edge.endArrow) attrs['marker-end'] = `url(#graph-arrow${bold ? '-bold' : ''})`;
  }
  const tip = `${edge.from} → ${edge.to}${edge.label ? `：${edge.label}` : ''}`;
  return group(ctx, [titleNode(ctx, tip), path(ctx, d, attrs, { kind: 'edge', from: edge.from, to: edge.to })], { kind: 'edge-group' });
}

function drawShape(ctx, item, n, a) {
  const { x, y, w, h } = n;
  const node = item.node;
  const stroke = node.class === 'ext' ? a.line2 : node.class && a[node.class] ? a[node.class] : a.line2;
  const fill = node.class === 'ext' ? 'none' : node.class && a[node.class] ? ctx.mix(a.node, a[node.class], a.soft) : a.node;
  const common = { fill, stroke, 'stroke-width': 1.25, ...(node.class === 'ext' ? { 'stroke-dasharray': '4 3' } : {}) };
  if (node.kind === 'start') return [ctx.circle(x + w / 2, y + h / 2, Math.min(w, h) / 2, { fill: a.fg2, stroke: 'none' })];
  if (node.kind === 'end') return [
    ctx.circle(x + w / 2, y + h / 2, Math.min(w, h) / 2, { fill: a.node, stroke: a.fg2, 'stroke-width': 1.5 }),
    ctx.circle(x + w / 2, y + h / 2, Math.min(w, h) / 2 - 4, { fill: a.fg2, stroke: 'none' }),
  ];
  if (node.kind === 'choice' || node.shape === 'diamond') return [ctx.shape('polygon', { points: points([[x + w / 2, y], [x + w, y + h / 2], [x + w / 2, y + h], [x, y + h / 2],]), ...common })];
  if (node.kind === 'fork' || node.kind === 'join') return [ctx.rect(x, y, w, h, { ...common, rx: 2 })];
  if (node.shape === 'circle') return [ctx.shape('ellipse', { cx: x + w / 2, cy: y + h / 2, rx: w / 2, ry: h / 2, ...common })];
  if (node.shape === 'hexagon') {
    const cut = 16;
    return [ctx.shape('polygon', { points: points([[x + cut, y], [x + w - cut, y], [x + w, y + h / 2], [x + w - cut, y + h], [x + cut, y + h], [x, y + h / 2]]), ...common })];
  }
  if (node.shape === 'stadium') return [ctx.rect(x, y, w, h, { ...common, rx: h / 2 })];
  if (node.shape === 'cylinder') {
    const ry = 6;
    return [
      path(ctx, `M${x} ${y + ry} C${x} ${y - ry * .2} ${x + w} ${y - ry * .2} ${x + w} ${y + ry} V${y + h - ry} C${x + w} ${y + h + ry * .2} ${x} ${y + h + ry * .2} ${x} ${y + h - ry} Z`, common),
      path(ctx, `M${x} ${y + ry} C${x} ${y + ry * 2} ${x + w} ${y + ry * 2} ${x + w} ${y + ry}`, common),
    ];
  }
  const rx = node.kind === 'state' ? 8 : node.shape === 'round' ? 11 : 3;
  const shape = ctx.rect(x, y, w, h, { ...common, rx });
  if (node.shape !== 'subroutine') return [shape];
  return [shape, path(ctx, `M${x + 9} ${y + 4} V${y + h - 4} M${x + w - 9} ${y + 4} V${y + h - 4}`, { fill: 'none', stroke, 'stroke-width': 1.25 })];
}

function drawNode(ctx, item, n, a) {
  const node = item.node, children = [titleNode(ctx, node.label || node.id), ...drawShape(ctx, item, n, a)];
  const nodeMeta = { kind: 'node', id: node.id, ...(node.class ? { status: node.class } : {}) };
  if (node.kind === 'start' || node.kind === 'end' || node.kind === 'choice' || node.kind === 'fork' || node.kind === 'join') return group(ctx, children, nodeMeta);
  if (node.kind === 'er' && n.er) {
    const er = n.er, pad = er.pad, ruleY = n.y + er.headerH;
    for (const [i, line] of er.headLines.entries()) children.push(text(ctx, n.x + n.w / 2, n.y + 7 + (i + .5) * 19, line, { anchor: 'middle', size: 14, weight: 600, fill: a.fg1 }, { kind: 'node-label', id: node.id }));
    children.push(path(ctx, `M${n.x + 1} ${ruleY} H${n.x + n.w - 1}`, { stroke: a.line2, 'stroke-width': 1 }));
    let rowY = ruleY + 2;
    for (const row of er.rows) {
      const rowChildren = [];
      if (row.comment) rowChildren.push(titleNode(ctx, `${row.name}${row.keys.length ? ` · ${row.keys.join(' ')}` : ''}：${row.comment}`));
      const cy = rowY + row.rowH / 2;
      row.typeLines.forEach((line, i) => rowChildren.push(text(ctx, n.x + pad, cy + (i - (row.typeLines.length - 1) / 2) * 17, line, { anchor: 'start', size: 13, fill: a.fg3 }, { kind: 'attribute-type', entity: node.id, attribute: row.name })));
      row.nameLines.forEach((line, i) => rowChildren.push(text(ctx, n.x + pad + er.typeW + 12, cy + (i - (row.nameLines.length - 1) / 2) * 17, line, { anchor: 'start', size: 13, fill: a.fg2 }, { kind: 'attribute', entity: node.id, attribute: row.name })));
      if (row.keyText) rowChildren.push(text(ctx, n.x + n.w - pad, cy, row.keyText, { anchor: 'end', size: 12, fill: a.fg3 }, { kind: 'attribute-key', entity: node.id, attribute: row.name }));
      children.push(group(ctx, rowChildren, { kind: 'attribute-row', entity: node.id, attribute: row.name }));
      rowY += row.rowH;
    }
    return group(ctx, children, nodeMeta);
  }
  const lines = item.titleLines || [], desc = item.descLines || [];
  const titleH = lines.length * 19, descH = desc.length * 17, gap = desc.length ? 7 : 0;
  const top = n.y + Math.max(10, (n.h - titleH - gap - descH) / 2);
  lines.forEach((line, i) => children.push(text(ctx, n.x + n.w / 2, top + i * 19 + 9.5, line, { anchor: 'middle', size: FONT.title.size, weight: FONT.title.weight, fill: a.fg1 }, { kind: 'node-label', id: node.id })));
  desc.forEach((line, i) => children.push(text(ctx, n.x + n.w / 2, top + titleH + gap + i * 17 + 8.5, line, { anchor: 'middle', size: FONT.body.size, fill: a.fg3 }, { kind: 'node-description', id: node.id })));
  return group(ctx, children, nodeMeta);
}

function scene(geometry, ctx, info = {}) {
  const a = appearance(ctx), model = geometry.model || {}, modelNodes = new Map((model.nodes || []).map(node => [node.id, node]));
  const framesLayer = [], edgeLayer = [], nodeLayer = [], edgeLabelLayer = [], titleLayer = [];
  for (const frame of geometry.frames || []) {
    const attrs = { fill: a.surface, stroke: frame.class && a[frame.class] ? a[frame.class] : a.line2, 'stroke-width': 1, 'stroke-dasharray': '5 4' };
    const frameChildren = [ctx.rect(frame.x, frame.y, frame.w, frame.h, { ...attrs, rx: 6 })];
    framesLayer.push(group(ctx, frameChildren, { kind: 'frame', id: frame.id, ...(frame.class ? { status: frame.class } : {}) }));
    if (frame.lines?.length) {
      const rect = frame.titleRect;
      const titleChildren = [ctx.rect(rect.x - 3, rect.y - 3, rect.w + 6, rect.h + 6, { fill: a.surface, rx: 2 })];
      frame.lines.forEach((line, i) => titleChildren.push(text(ctx, rect.x, rect.y + (i + .5) * 17, line, { anchor: 'start', size: 13, weight: 600, fill: a.fg3 }, { kind: 'frame-title', id: frame.id })));
      (frame.descLines || []).forEach((line, i) => titleChildren.push(text(ctx, rect.x, rect.y + frame.lines.length * 17 + 4 + i * 16 + 8, line, { anchor: 'start', size: 13, fill: a.fg3 }, { kind: 'frame-description', id: frame.id })));
      titleLayer.push(group(ctx, titleChildren, { kind: 'frame-title-group', id: frame.id }));
    }
  }
  for (const edge of geometry.edges || []) {
    const rendered = edgePath(edge, modelNodes, ctx, a);
    if (rendered) edgeLayer.push(rendered);
    if (edge.labelRect && edge.labelLines?.length) {
      const r = edge.labelRect, children = [ctx.rect(r.x, r.y, r.w, r.h, { fill: a.surface, rx: 3 })];
      edge.labelLines.forEach((line, i) => children.push(text(ctx, r.x + r.w / 2, r.y + r.h / 2 + (i - (edge.labelLines.length - 1) / 2) * 16, line, { anchor: 'middle', size: 12, fill: a.fg3 }, { kind: 'edge-label' })));
      edgeLabelLayer.push(group(ctx, children, { kind: 'edge-label-group', from: edge.from, to: edge.to }));
    }
  }
  for (const n of geometry.nodes || []) {
    const item = modelNodes.get(n.id);
    if (item) nodeLayer.push(drawNode(ctx, { node: item, titleLines: n.lines, descLines: n.descLines }, n, a));
  }
  const children = [defs(ctx, a), ...framesLayer,
    group(ctx, edgeLayer, { kind: 'edges' }), group(ctx, nodeLayer, { kind: 'nodes' }),
    group(ctx, edgeLabelLayer, { kind: 'edge-labels' }), group(ctx, titleLayer, { kind: 'frame-titles' })];
  return { width: geometry.width, height: geometry.height, children, ...(info.title ? { title: info.title } : {}) };
}

const implementations = Object.fromEntries(['flowchart', 'stateDiagram-v2', 'erDiagram'].map(kind => [kind, {
  optionMode: 'raw',
  parse: (body, info) => parseGraph(body, info),
  layout: (model, options, info) => layoutGraph(model, options, info),
  scene,
}]));

export { implementations };

/* 分层架构 / 无层能力分组；同层共用网格行数，文字不折行。 */

import { FONT, appearance, error, parseIndented, snap, wrapText } from './support.js';

const LIMITS = { layers: 8, groups: 6, items: 30, labelWidth: 208 };
const GAP = 12, PAD = 12, ITEM_GAP = 8, ITEM_H = 32, DB_H = 56, HEADER = 40;
const issue = (lang, line, zh, en, fixZh = '拆成两张图，或把说明移到图外', fixEn = 'Split into two diagrams, or move descriptions outside the diagram') => error(lang, line, zh, en, fixZh, fixEn);

function parse(source, info) {
  const ctx = { ...info, lang: info.lang, firstLine: info.firstLine, options: info.options || {} };
  const { items: roots, errors } = parseIndented(source, ctx);
  const { lang, options } = ctx;
  for (const key of Object.keys(options)) errors.push(issue(lang, ctx.firstLine - 1, `layers 不支持选项「${key}」`, `Unsupported layers option: ${key}`, '移除这个选项', 'Remove this option'));
  const isGroup = (node) => /[:：]/.test(node.text.split('|')[0]) || (!node.text.includes('|') && node.children.some((child) => /^[^:：>]+>/.test(child.text)));
  const modes = roots.map(isGroup);
  if (modes.some(Boolean) && modes.some((mode) => !mode)) errors.push(issue(lang, roots[modes.findIndex((mode) => mode !== modes[0])].line, '顶层不能混用层与分组', 'Do not mix layers and groups at the top level', '顶层全部写成层，或全部写成分组', 'Use only layers or only groups at the top level'));
  function capabilities(text, line) {
    const result = text.split(/[,，]/).map((part) => {
      const label = part.trim(), mark = label.match(/^([+~=])\s*/)?.[1] || '';
      if (!label || !label.replace(/^[+~=]\s*/, '')) errors.push(issue(lang, line, '能力项名称不能为空', 'Capability labels cannot be empty', '删除空项或补上名称', 'Remove the empty item or add a label'));
      return { label: mark ? `${mark} ${label.replace(/^[+~=]\s*/, '')}` : label, mark, tone: ({ '+': 'new', '~': 'info', '=': 'ok' })[mark] || '', line };
    });
    return result;
  }
  function group(node) {
    const parts = node.text.split(/[:：]/);
    const header = parts.shift().trim();
    const flag = header.match(/\s*\{(db|ext)\}$/)?.[1] || '';
    const title = header.replace(/\s*\{(db|ext)\}$/, '').trim();
    if (!title || /[{}|>]/.test(title)) errors.push(issue(lang, node.line, '分组名称或标志无效', 'Invalid group name or flag', '使用「名称 {db}: 项, 项」或普通名称', 'Use "Name {db}: item, item" or a plain name'));
    const result = { title, flag, line: node.line, items: [], categories: [] };
    if (parts.length) {
      result.items = capabilities(parts.join(':'), node.line);
      if (node.children.length) errors.push(issue(lang, node.children[0].line, '行内能力项不能再带子项', 'Inline capabilities cannot have children', '改成分类行写法，或删除子项', 'Use category rows, or remove the children'));
    } else {
      if (!node.children.length) errors.push(issue(lang, node.line, '分组中没有能力项', 'Group has no capabilities', '在名称后加「: 项, 项」，或添加分类行', 'Add ": item, item" or category rows'));
      for (const child of node.children) {
        const match = child.text.match(/^(.+?)\s*>\s*(.+)$/);
        if (!match || child.children.length) {
          errors.push(issue(lang, child.children[0]?.line || child.line, '分类行写法无效', 'Invalid category row', '使用「- 分类 > 项, 项」，不嵌套子项', 'Use "- Category > item, item" without nesting'));
          continue;
        }
        const row = { label: match[1].trim(), line: child.line, items: capabilities(match[2], child.line) };
        result.categories.push(row);
        result.items.push(...row.items);
      }
    }
    if (result.items.length > LIMITS.items) errors.push(issue(lang, node.line, `每组最多 ${LIMITS.items} 项`, `At most ${LIMITS.items} capabilities per group`));
    return result;
  }
  const layered = !modes.some(Boolean);
  const layers = layered ? roots.map((node) => {
    const [title, ...desc] = node.text.split('|').map((s) => s.trim());
    if (!title || /[{}>]/.test(title)) errors.push(issue(lang, node.line, '层名称无效', 'Invalid layer name', '使用「- 层名 | 说明」', 'Use "- Layer | description"'));
    if (!node.children.length) errors.push(issue(lang, node.line, '层中没有分组', 'Layer has no groups', '给这一层添加分组和能力项', 'Add groups and capabilities to this layer'));
    if (node.children.length > LIMITS.groups) errors.push(issue(lang, node.line, `每层最多 ${LIMITS.groups} 组`, `At most ${LIMITS.groups} groups per layer`));
    return { title, description: desc.join(' | '), line: node.line, groups: node.children.map(group) };
  }) : [];
  const groups = layered ? [] : roots.map(group);
  if (!roots.length) errors.push(issue(lang, ctx.firstLine, '图中没有条目', 'Diagram is empty', '添加层、分组与能力项', 'Add layers, groups and capabilities'));
  if (layered && layers.length > LIMITS.layers) errors.push(issue(lang, roots[LIMITS.layers].line, `最多 ${LIMITS.layers} 层`, `At most ${LIMITS.layers} layers`));
  return { model: { type: 'layers', layered, layers, groups }, errors };
}

function layout(model, { measure, width, lang }) {
  const errors = [], groups = [], layers = [], nodes = [];
  const all = model.layered ? model.layers.flatMap((l) => l.groups) : model.groups;
  for (const group of all) for (const item of group.items) {
    if (measure(item.label.replace(/^[+~=]\s*/, ''), FONT.body) > LIMITS.labelWidth) errors.push(issue(lang, item.line, `能力项「${item.label}」过长`, `Capability label is too long: ${item.label}`, '把说明移到图外，名称缩短至约 16 个汉字', 'Move descriptions outside; shorten the label to about 16 CJK characters'));
  }
  if (errors.length) return { width, height: 0, errors };
  const cellW = (g, pad) => snap(Math.max(g.flag === 'db' ? 80 : 64, ...g.items.map((item) => measure(item.label, FONT.body) + pad)));
  const rowsOf = (g, rows) => g.flag === 'db' ? Math.max(1, Math.round((rows * ITEM_H + (rows - 1) * ITEM_GAP) / (DB_H + ITEM_GAP))) : rows;
  const colsOf = (g, rows) => Math.max(1, Math.ceil(g.items.length / rowsOf(g, rows)));
  const categoryLabelW = (g) => snap(Math.max(0, ...g.categories.map((row) => measure(row.label, FONT.body))) + 16);
  function groupW(g, rows, pad) {
    let inside;
    if (g.categories.length) {
      inside = categoryLabelW(g) + ITEM_GAP + Math.max(...g.categories.map((row) => row.items.reduce((n, item) => n + snap(Math.max(64, measure(item.label, FONT.body) + pad)), 0) + ITEM_GAP * (row.items.length - 1)));
    } else {
      const cols = colsOf(g, rows);
      inside = cols * cellW(g, pad) + ITEM_GAP * (cols - 1);
    }
    return snap(Math.max(inside, measure(g.title, FONT.title)) + PAD * 2);
  }
  const groupH = (g, rows) => HEADER + PAD + (g.categories.length ? g.categories.length * (g.flag === 'db' ? DB_H : ITEM_H) + (g.categories.length - 1) * ITEM_GAP : rowsOf(g, rows) * (g.flag === 'db' ? DB_H : ITEM_H) + (rowsOf(g, rows) - 1) * ITEM_GAP);
  const total = (gs, rows, pad) => gs.reduce((n, g) => n + groupW(g, rows, pad), 0) + GAP * (gs.length - 1);
  // 余宽按理想宽度分配；4px 网格向下取整，尾组吸收余数。
  function distribute(mins, ideals, space) {
    const extra = Math.max(0, space - mins.reduce((a, b) => a + b, 0));
    const sum = ideals.reduce((a, b) => a + b, 0);
    const ws = mins.map((min, i) => min + Math.floor(extra * ideals[i] / sum / 4) * 4);
    ws[ws.length - 1] += space - ws.reduce((a, b) => a + b, 0);
    return ws;
  }
  let id = 0;
  function placeGroup(g, x, y, w, h, rows, color) {
    const placed = { ...g, x, y, w, h, rows, color, id: `group-${id++}`, nodes: [], categoryNodes: [] };
    groups.push(placed);
    const makeNode = (item, nx, ny, nw, nh, category = false) => {
      const node = { ...item, x: nx, y: ny, w: nw, h: nh, shape: !category && g.flag === 'db' ? 'db' : 'rect', group: placed.id, category, color };
      nodes.push(node);
      (category ? placed.categoryNodes : placed.nodes).push(node);
    };
    const inside = w - PAD * 2;
    if (g.categories.length) {
      const labelW = categoryLabelW(g), ih = g.flag === 'db' ? DB_H : ITEM_H;
      g.categories.forEach((row, ri) => {
        const ny = y + HEADER + ri * (ih + ITEM_GAP);
        makeNode({ label: row.label, line: row.line }, x + PAD, ny, labelW, ih, true);
        const mins = row.items.map((item) => snap(Math.max(64, measure(item.label, FONT.body) + 16)));
        const ws = distribute(mins, mins.map((n) => n + 8), inside - labelW - ITEM_GAP * row.items.length);
        let nx = x + PAD + labelW + ITEM_GAP;
        row.items.forEach((item, i) => { makeNode(item, nx, ny, ws[i], ih); nx += ws[i] + ITEM_GAP; });
      });
    } else {
      const cols = colsOf(g, rows), ih = g.flag === 'db' ? DB_H : ITEM_H;
      const countRows = Math.ceil(g.items.length / cols);
      // 分组标题下的网格统一从顶部排起：同排各组首行对齐，多出的高度留在底部。
      const top = y + HEADER;
      for (let ri = 0; ri < countRows; ri += 1) {
        const items = g.items.slice(ri * cols, (ri + 1) * cols);
        const db = g.flag === 'db';
        const count = db ? cols : items.length;
        const cw = Math.floor((inside - (count - 1) * ITEM_GAP) / count / 4) * 4;
        let nx = x + PAD + (db ? Math.floor((inside - (items.length * cw + (items.length - 1) * ITEM_GAP)) / 8) * 4 : 0);
        items.forEach((item, ci) => {
          const nw = !db && ci === items.length - 1 ? x + w - PAD - nx : cw;
          makeNode(item, nx, top + ri * (ih + ITEM_GAP), nw, ih);
          nx += cw + ITEM_GAP;
        });
      }
    }
    return placed;
  }
  let actualWidth = Math.floor(width), y = 4;
  if (model.layered) {
    // 左栏宽度同时计入层名与说明：说明先按自身长度要求宽度（上有上限），再按词换行。
    const DESC_MAX = 120;
    const titleNeed = (l) => measure(l.title, FONT.title) + 16;
    const descNeed = (l) => (l.description ? Math.min(DESC_MAX, measure(l.description, FONT.label) + 8) : 0);
    const labelWidth = snap(Math.max(80, ...model.layers.map((l) => Math.max(titleNeed(l), descNeed(l)))));
    const nameWidth = Math.min(labelWidth, 160);
    if (labelWidth > 160 && model.layers.some((l) => titleNeed(l) > 160)) errors.push(issue(lang, model.layers.find((l) => titleNeed(l) > 160).line, '层名称过长', 'Layer name is too long', '缩短层名，把说明放在「|」之后', 'Shorten the name; put descriptions after "|"'));
    const left = 4 + nameWidth + GAP;
    // 先求每层单列所需宽度，保证窄屏返回固有最小宽度，而不是缩小字号。
    for (const layer of model.layers) actualWidth = Math.max(actualWidth, left + total(layer.groups, LIMITS.items * 2, 16) + 4);
    const available = actualWidth - left - 4;
    for (const layer of model.layers) {
      let rows = 1;
      while (rows < LIMITS.items * 2 && total(layer.groups, rows, 16) > available) rows += 1;
      const mins = layer.groups.map((g) => groupW(g, rows, 16)), ideals = layer.groups.map((g) => groupW(g, rows, 24));
      const widths = distribute(mins, ideals, available - GAP * (layer.groups.length - 1));
      const descriptionLines = layer.description ? wrapText(layer.description, nameWidth - 8, FONT.label, measure) : [];
      const h = Math.max(...layer.groups.map((g) => groupH(g, rows)), 32 + descriptionLines.length * 16);
      const color = layers.length % 6 + 1;
      layers.push({ ...layer, x: 4, y, w: nameWidth, h, rows, color, descriptionLines });
      let x = left;
      layer.groups.forEach((g, i) => { placeGroup(g, x, y, widths[i], h, rows, color); x += widths[i] + GAP; });
      y += h + 16;
    }
